import {validateLoreAction,explicitLoreNavigation,loreActionMarkup,loreCaseSources,loreEvidenceAnswer,loreYearAnswer,loreStatusAnswer,renderLoreApiReply} from './lore_tools.js';
const ICONS={overview:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',map:'<path d="m9 18-6 3V6l6-3 6 3 6-3v15l-6 3-6-3Z"/><path d="M9 3v15M15 6v15"/>',layers:'<path d="m12 3 10 6-10 6L2 9l10-6Z"/><path d="m2 13 10 6 10-6M2 17l10 6 10-6"/>',sources:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 7h6M9 11h6M9 15h4"/>',report:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8l-6-6Z"/><path d="M14 2v6h6M8 13h8M8 17h5"/>',activity:'<path d="M2 12h5l3-8 4 16 3-8h5"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M6.1 7a7 7 0 0 1 11.6-2L20 8M4 16l2.3 3A7 7 0 0 0 18 17"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v.1"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',mountain:'<path d="m3 20 7-15 5 10 3-6 5 11H3Z"/><path d="m7 11 3 2 2-3"/>',droplet:'<path d="M12 3S5 11 5 15a7 7 0 0 0 14 0c0-4-7-12-7-12Z"/><path d="M8 16a4 4 0 0 0 4 3"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0Z"/><circle cx="12" cy="10" r="3"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',external:'<path d="M14 3h7v7M21 3 10 14"/><path d="M10 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-5"/>',check:'<path d="m5 12 4 4L19 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',sparkles:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z"/>',dialogue:'<path d="M21 11a8 8 0 0 1-8 8H6l-4 3 2-6a8 8 0 1 1 17-5Z"/><path d="M8 9h8M8 13h5"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>'};
export const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]||ICONS.info}</svg>`;
export const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escapeHTML;
export const normalize=value=>String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
export const validCoordinates=c=>Array.isArray(c)&&c.length>=2&&c.slice(0,2).every(Number.isFinite)&&Math.abs(c[0])<=180&&Math.abs(c[1])<=90;
export function groupCaseCoordinates(cases){const groups=new Map();for(const c of cases.filter(c=>validCoordinates(c.coordinates))){const key=c.coordinates.slice(0,2).join(',');if(!groups.has(key))groups.set(key,{coordinates:c.coordinates.slice(0,2),cases:[]});groups.get(key).cases.push(c);}return [...groups.values()];}
export const safeURL=value=>{try{const u=new URL(String(value),location.href);return ['https:','http:'].includes(u.protocol)?u.href:'#';}catch{return '#';}};
const months=['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
export const STATIC=document.documentElement.dataset.static==='1';
function apiURL(name,params={}){const clean=Object.fromEntries(Object.entries(params).filter(([,v])=>v));if(!STATIC)return `/api/${name}?${new URLSearchParams(clean)}`;return `static/${[name,clean.company,clean.period].filter(Boolean).join('_')}.${name==='report'?'html':'json'}`;}
async function savedReading(caseId){const response=await fetch(STATIC?'static/readings.json':'/api/readings',{headers:{Accept:'application/json'}});if(!response.ok)return null;return ((await response.json()).readings||{})[caseId]||null;}
function periodLabel(value,short=false){const m=/^(\d{4})-(\d{2})$/.exec(String(value));return m&&+m[2]>=1&&+m[2]<=12?`${short?months[+m[2]-1].slice(0,3):months[+m[2]-1]} ${m[1]}`:String(value||'Período no informado');}
const dateLabel=value=>{if(!value)return 'Fecha no informada';if(/^\d{4}-\d{2}$/.test(value))return periodLabel(value);const d=new Date(value);return Number.isNaN(d.valueOf())?String(value):new Intl.DateTimeFormat('es-PE',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(d);};
const titleCase=value=>String(value||'').replace(/^./,m=>m.toUpperCase());
const number=value=>Number.isFinite(Number(value))&&value!==null?new Intl.NumberFormat('es-PE').format(Number(value)):'—';
const text=value=>typeof value==='string'?value:(value?.description||value?.text||value?.claim||value?.title||JSON.stringify(value));
const statusClass=status=>normalize(status).includes('latent')?'latent':normalize(status).includes('activ')?'active':'unknown';
const statusBadge=status=>`<span class="status-pill ${statusClass(status)}">${e(status||'Sin estado')}</span>`;
const collection=value=>value?.type==='FeatureCollection'?value:value?.type==='Feature'?{type:'FeatureCollection',features:[value]}:Array.isArray(value)?{type:'FeatureCollection',features:value.filter(f=>f?.type==='Feature')}:{type:'FeatureCollection',features:[]};
const hasGeo=value=>collection(value).features.length>0;

export function normalizePortfolio(raw={}){const cases=Array.isArray(raw.cases)?raw.cases:[],sources=Array.isArray(raw.sources)?raw.sources:[],summary=raw.summary||{};return {...raw,company:raw.company||{},period:raw.period||'',periods:(raw.periods||[]).map(p=>typeof p==='string'?p:p.period||p.id).filter(Boolean),cases,sources,summary:{cases:summary.cases??cases.length,active:summary.active??cases.filter(c=>statusClass(c.status)==='active').length,latent:summary.latent??cases.filter(c=>statusClass(c.status)==='latent').length,dialogue:summary.dialogue??cases.filter(c=>normalize(c.phase).includes('dialog')).length,sources:summary.sources??sources.length,observations:summary.observations??cases.reduce((n,c)=>n+(c.observations||[]).length,0)},geography:raw.geography||{},coverage:raw.coverage||{},insights:Array.isArray(raw.insights)?raw.insights:[]};}
export function filterCases(cases,query='',status=''){const q=normalize(query).trim();return cases.filter(c=>(!q||normalize([c.name,c.region,c.province,c.district,c.summary].filter(Boolean).join(' ')).includes(q))&&(!status||statusClass(c.status)===status));}
export function buildEvolution(payload){if(Array.isArray(payload.historical_series)&&payload.historical_series.length)return payload.historical_series.filter(r=>r.period).map(r=>({...r,active:r.active===null?null:Number(r.active)||0,latent:r.latent===null?null:Number(r.latent)||0,observed:Number(r.observed)||0})).sort((a,b)=>a.period.localeCompare(b.period));const periods=new Map();for(const c of payload.cases||[])for(const observation of c.observations||[]){if(!observation.period)continue;if(!periods.has(observation.period))periods.set(observation.period,new Map());periods.get(observation.period).set(c.id,observation);}return [...periods].map(([period,rows])=>({period,active:[...rows.values()].filter(o=>statusClass(o.status)==='active').length,latent:[...rows.values()].filter(o=>statusClass(o.status)==='latent').length,observed:rows.size})).sort((a,b)=>a.period.localeCompare(b.period));}
const institutionCatalog=[{name:'Defensoría del Pueblo',short:'DP',match:['defensoria']},{name:'Policía Nacional del Perú',short:'PNP',match:['pnp','policia']},{name:'OEFA',short:'OEFA',match:['oefa']},{name:'Ministerio de Energía y Minas',short:'MINEM',match:['minem','energia y minas']},{name:'Ministerio del Ambiente',short:'MINAM',match:['minam','ministerio del ambiente']},{name:'Presidencia del Consejo de Ministros',short:'PCM',match:['pcm','consejo de ministros']},{name:'Prensa',short:'Prensa',match:['prensa','medio','periodis']}];
export function sourceCoverage(payload){const matrix=payload.source_matrix||[];return institutionCatalog.map(institution=>{const match=matrix.find(row=>institution.match.some(k=>normalize(row.institution).includes(k)));const docs=(payload.sources||[]).filter(s=>institution.match.some(k=>normalize(s.institution).includes(k)));return {...institution,count:match?.count??docs.length,status:match?.status|| (docs.length?'directa':'sin_fuente_directa'),note:match?.note|| (docs.length?'Documentos incorporados al corpus.':'Sin documentos de esta institución incorporados a esta cartera.')};});}

const state={company:'mineria',period:'',view:'resumen',payload:null,geo:null,selectedCase:null,query:'',status:'',maps:[],threeD:true,requestId:0,chartAll:false};
const $=selector=>document.querySelector(selector);
const viewTitles={pais:['PANORAMA NACIONAL','Todos los conflictos, en un solo lugar.','Los conflictos activos del Perú según la Defensoría, tus departamentos y catorce años de historia.'],alertas:['ALERTA TEMPRANA','Lo que conviene gestionar hoy.','Señales reportadas por las fuentes, con la regla que las activa y su evidencia.'],sistema:['AUTOMATIZACIÓN Y PRUEBAS','El monitoreo, funcionando.','Cada fuente se lee sola cada día. Aquí está el registro de cada ejecución.'],resumen:['VISIÓN DE TU CARTERA','Tu territorio, en perspectiva.','Una lectura integrada del contexto socioambiental, con cada hallazgo conectado a su evidencia.'],territorio:['INTELIGENCIA ESPACIAL','El contexto tiene un lugar.','Explora las relaciones territoriales y las capas disponibles para esta cartera.'],conflictos:['SEGUIMIENTO DOCUMENTADO','Cada caso, en su contexto.','Estados reportados, demandas, compromisos y evolución a través de las fuentes.'],fuentes:['EVIDENCIA Y CONTRASTE','Distintas fuentes. Una perspectiva.','Conoce qué instituciones sustentan el monitoreo y dónde persisten vacíos de cobertura.'],reportes:['DE LA EVIDENCIA A LA DECISIÓN','El mes, con perspectiva.','Un reporte ejecutivo con contexto territorial, evolución y fuentes verificables.']};
let toastTimer;
function toast(message){const node=$('#toast');node.textContent=message;node.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.remove('visible'),6500);}
function hydrateIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
function reportURL(){const params=new URLSearchParams({company:state.company});if(state.period)params.set('period',state.period);const url=apiURL('report',Object.fromEntries(params));return state.session?url+(url.includes('?')?'&':'?')+'analista='+encodeURIComponent(state.session.user):url;}
function heading(){const [eyebrow,title,description]=viewTitles[state.view];const p=state.payload;const periods=[...new Set([p.period,...p.periods].filter(Boolean))].sort().reverse();return `<header class="page-heading"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${description}</p></div><div class="heading-actions"><label class="period-control">${icon('calendar')}<span class="visually-hidden">Período del reporte</span><select id="period-select">${periods.length?periods.map(v=>`<option value="${e(v)}" ${v===p.period?'selected':''}>${e(titleCase(periodLabel(v)))}</option>`).join(''):'<option value="">Período no informado</option>'}</select></label><a class="button button-primary" href="${reportURL()}" target="_blank" rel="noopener">${icon('download')}Reporte mensual</a></div></header>`;}
function metric(label,value,note,iconName,accent=false){return `<article class="kpi ${accent?'accent':''}"><div class="kpi-top">${label}<span class="kpi-icon">${icon(iconName)}</span></div><div class="kpi-value">${number(value)}</div><div class="kpi-note"><i></i>${note}</div></article>`;}
function metrics(){const s=state.payload.summary;return `<section class="kpi-grid" aria-label="Indicadores de la cartera">${metric('Casos documentados',s.cases,'En la cartera del período','layers',true)}${metric('En estado activo',s.active,`${number(s.latent)} latentes documentados`,'activity')}${metric('Con diálogo reportado',s.dialogue,'Según la evidencia incorporada','dialogue')}${metric('Fuentes documentales',s.sources,'Documentos del corpus consultado','sources')}</section>`;}
function mapPanel(big=false){const geo=state.geo||state.payload.geography||{},mapped=state.payload.cases.filter(c=>validCoordinates(c.coordinates)).length;return `<section class="panel"><div class="panel-heading"><div><h2>${icon('map')}Panorama territorial</h2><p class="panel-subtitle">${e(state.payload.company.operation||state.payload.company.name||'Cartera seleccionada')}</p></div>${!big?'<a class="text-link" href="#territorio">Explorar '+icon('arrow')+'</a>':''}</div><div class="map-toolbar"><span class="map-location">${icon('pin')}${e(state.payload.company.region||'Perú · cartera seleccionada')}</span><div class="segmented" aria-label="Perspectiva del mapa"><button data-map-view="2d" class="${!state.threeD?'active':''}">2D</button><button data-map-view="3d" class="${state.threeD?'active':''}">3D</button></div>${basemapToggle()}</div><div class="map-wrap"><div class="territory-map ${big?'big-map':''}" id="territory-map" role="region" aria-label="Mapa territorial de la cartera"><div class="map-fallback">${icon('map')}<strong>Preparando el territorio</strong><p>Las ubicaciones se mostrarán según la precisión disponible en las fuentes.</p></div></div><div class="map-layer-panel"><strong>Capas del territorio</strong>${layerToggle('cases','Casos documentados',mapped>0,true)}${layerToggle('boundary','Límites administrativos',hasGeo(geo.boundary),true)}${layerToggle('operations','Operaciones',hasGeo(geo.operations),true)}${layerToggle('communities','Comunidades',hasGeo(geo.communities),false)}${layerToggle('roads','Red vial',hasGeo(geo.roads),false)}${layerToggle('wells','Pozos',hasGeo(geo.wells),false)}${(geo.history_points?.features?.length)?layerToggle('history','Focos de conflicto 2012-2025',true,true):''}${geoperuLayers().length?'<strong class="layer-group">GEOPERÚ</strong>':''}${geoperuLayers().map(l=>layerToggle(l.key,`${l.label} (${l.count})`,true,false)).join('')}</div><div class="map-legend"><span><i class="legend-dot"></i>Activo</span><span><i class="legend-dot latent"></i>Latente</span><span>Ubicaciones referenciales</span></div></div><div class="map-attribution-note">${icon('info')}<span>${mapped} de ${state.payload.cases.length} casos con coordenadas. La precisión y antigüedad de cada capa se conservan en su fuente.</span></div>${figCaption('Conflictos activos de la cartera (puntos), límites distritales y, si las activas, capas de GEOPERÚ: concesiones de la empresa, comunidades tituladas, cuencas, áreas protegidas y pasivos ambientales.','Defensoría del Pueblo (casos); GEOPERÚ del MINAM por ArcGIS REST (capas); relieve Copernicus GLO-30.',`Casos: ${periodLabel(state.payload.period)}. Capas: ${((state.geo||{}).geoperu||{}).fetched_at?dateLabel(state.geo.geoperu.fetched_at):'copia versionada'}.`)}</section>`;}
function layerToggle(id,label,available,checked){return `<label class="layer-toggle ${available?'':'disabled'}"><input type="checkbox" data-layer="${id}" ${available?'':'disabled'} ${available&&checked?'checked':''}>${label}${available?'':'<small>sin datos</small>'}</label>`;}
function signals(){const p=state.payload;const entries=p.insights.length?p.insights.slice(0,3):p.cases.slice(0,3).map(c=>({type:'seguimiento',title:c.name,text:c.summary,case_id:c.id,source_ids:c.source_ids||[]}));return `<section class="panel"><div class="panel-heading"><div><h2>${icon('activity')}Lecturas del período</h2><p class="panel-subtitle">Señales para orientar tu revisión</p></div><span class="source-badge">${e(periodLabel(p.period,true))}</span></div><div class="signal-list">${entries.length?entries.map(item=>`<button class="signal-item" data-case="${e(item.case_id||'')}" ${item.case_id?'':'data-insight="true"'}><div class="signal-meta"><span class="status-pill ${item.type==='discrepancia'?'active':'dialogue'}">${e(item.type==='discrepancia'?'Fuentes por contrastar':item.type==='contexto'?'Contexto':'Seguimiento')}</span></div><h3 class="signal-title">${e(item.title)}</h3><p class="signal-description">${e(item.text||'Consulta la evidencia disponible en la ficha del caso.')}</p><span class="signal-footer">${icon('sources')}${(item.source_ids||[]).length?`${item.source_ids.length} fuentes relacionadas`:'Revisar ficha documental'}${icon('arrow')}</span></button>`).join(''):empty('Sin lecturas para este período','Incorpora documentos para construir el seguimiento de esta cartera.')}</div><div class="panel-footer"><span>Hallazgos documentales, no predicciones</span><a class="text-link" href="#conflictos">Ver casos ${icon('arrow')}</a></div></section>`;}
function empty(title,description){return `<div class="empty-state">${icon('layers')}<h3>${e(title)}</h3><p>${e(description)}</p></div>`;}
function evolutionChart(){let rows=buildEvolution(state.payload);if(!state.chartAll)rows=rows.slice(-12);if(!rows.length)return empty('Historia aún no incorporada','La evolución requiere observaciones del mismo caso en diferentes períodos.');const w=540,h=140,pad={x:30,y:15},plotW=w-2*pad.x,plotH=85,max=Math.max(1,...rows.map(r=>r.active+r.latent));const x=i=>pad.x+(rows.length===1?plotW/2:i*plotW/(rows.length-1));const y=v=>plotH+pad.y-v/max*plotH;const labels=new Set([0,Math.floor((rows.length-1)/3),Math.floor((rows.length-1)*2/3),rows.length-1]);const line=key=>{let d='',pen=false;rows.forEach((r,i)=>{if(r[key]===null||r.observed===0){pen=false;return;}const prev=rows[i-1];if(prev){const [a,b]=prev.period.split('-').map(Number),[c,f]=r.period.split('-').map(Number);if(c*12+f-(a*12+b)>1)pen=false;}d+=`${pen?'L':'M'}${x(i).toFixed(1)},${y(r[key]).toFixed(1)} `;pen=true;});return d;};return `<svg class="evolution-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Evolución de casos activos y latentes de esta cartera">${[0,.5,1].map(f=>`<line x1="${pad.x}" y1="${y(max*f)}" x2="${w-pad.x}" y2="${y(max*f)}" stroke="#eaf0e4" stroke-dasharray="3 5"/><text x="15" y="${y(max*f)+3}" font-size="8" fill="#b0bba3" text-anchor="end">${number(max*f)}</text>`).join('')}<path d="${line('active')}" fill="none" stroke="#7ba38c" stroke-width="2"/><path d="${line('latent')}" fill="none" stroke="#d4ba8d" stroke-width="1.8"/>${rows.map((r,i)=>labels.has(i)?`<text x="${x(i)}" y="125" text-anchor="middle" font-size="8" fill="#a3b097">${e(periodLabel(r.period,true))}</text>`:'').join('')}${rows.length===1?`<circle cx="${x(0)}" cy="${y(rows[0].active)}" r="3" fill="#7ba38c"/>`:''}</svg><div class="chart-legend"><span><i></i>Activos</span><span><i class="latent"></i>Latentes</span><span>Casos observados · vacíos sin imputar</span></div>`;}
function phaseSummary(){const counts=new Map();for(const c of state.payload.cases){const phase=c.phase||'Sin fase documentada';counts.set(phase,(counts.get(phase)||0)+1);}return [...counts].map(([phase,n])=>`<span class="phase-chip">${e(phase)}<strong>${n}</strong></span>`).join('');}
export function classifyDocumentedPhase(value){const v=normalize(value);if(v.includes('desescalamiento'))return 'desescalamiento';if(v.includes('acuerdo'))return 'acuerdos';if(v.includes('temprana'))return 'temprana';if(v.includes('escalamiento'))return 'escalamiento';if(v.includes('crisis'))return 'crisis';return null;}
function phaseOverview(){const stages=[{id:'temprana',label:'Fase temprana',x:42,y:81},{id:'escalamiento',label:'Escalamiento',x:148,y:46},{id:'crisis',label:'Crisis',x:254,y:24},{id:'desescalamiento',label:'Desescalamiento',x:360,y:57},{id:'acuerdos',label:'Acuerdos',x:466,y:81}];const counts=Object.fromEntries(stages.map(s=>[s.id,0]));let unknown=0;for(const c of state.payload.cases){const phase=classifyDocumentedPhase(c.phase);if(phase)counts[phase]++;else unknown++;}return `<section class="panel phase-panel"><div class="panel-heading"><div><h2>${icon('activity')}¿En qué momento se encuentran los casos?</h2><p class="panel-subtitle">Fase documentada en el período · no es una proyección de riesgo</p></div><span class="source-badge">${number(state.payload.summary.dialogue)} con diálogo reportado</span></div><div class="phase-flow"><svg viewBox="0 0 508 135" role="img" aria-label="Distribución en fases documentadas: ${e(stages.map(s=>`${s.label}: ${counts[s.id]}`).join(', '))}"><path d="M42 81 C90 81 105 58 148 46 S211 14 254 24 S312 53 360 57 S421 81 466 81" fill="none" stroke="#e4ebdd" stroke-width="2"/>${stages.map(s=>`<circle cx="${s.x}" cy="${s.y}" r="${counts[s.id]?7:4}" fill="${counts[s.id]?'#7fa18b':'#dce6d3'}" stroke="white" stroke-width="2"/>${counts[s.id]?`<rect x="${s.x-14}" y="${s.y-28}" width="28" height="18" rx="5" fill="#e7f0e2"/><text x="${s.x}" y="${s.y-16}" text-anchor="middle" font-size="10" font-weight="600" fill="#6d8b59">${counts[s.id]}</text>`:''}<text x="${s.x}" y="113" text-anchor="middle" font-size="9" fill="${counts[s.id]?'#70905d':'#a2b296'}">${s.label}</text>`).join('')}</svg></div><div class="panel-footer"><span>Secuencia conceptual. La fase conserva la denominación publicada; el diálogo se registra aparte.</span>${unknown?`<span>${unknown} sin fase homologable</span>`:'<span>Sin fases inferidas</span>'}</div>${figCaption('Cuántos conflictos activos hay en cada fase del ciclo de la Defensoría (temprana, escalamiento, crisis, desescalamiento, acuerdos).','Defensoría del Pueblo, ficha de cada caso.',periodLabel(state.payload.period))}</section>`;}
function lowerPanels(){const coverage=sourceCoverage(state.payload);const direct=coverage.filter(s=>s.count>0);return `<section class="lower-grid"><article class="panel"><div class="panel-heading"><div><h2>${icon('clock')}Evolución documentada</h2><p class="panel-subtitle">Antecedentes incorporados al corpus de la cartera</p></div><button class="text-link" id="chart-range">${state.chartAll?'Últimos 12 registros':'Serie completa'} ${icon('arrow')}</button></div><div class="evolution-body">${evolutionChart()}${state.payload.coverage.historical_status?`<p class="history-note">${e(state.payload.coverage.historical_status)}</p>`:''}</div><div class="phase-list">${phaseSummary()}</div></article><article class="panel"><div class="panel-heading"><div><h2>${icon('sources')}Una lectura desde las fuentes</h2><p class="panel-subtitle">Cobertura institucional de la cartera</p></div><a class="text-link" href="#fuentes">Revisar ${icon('arrow')}</a></div><p class="coverage-blurb">${direct.length?`<strong>${direct.length} de ${coverage.length} categorías</strong> con documentos incorporados. El contraste se evalúa por caso, conservando coincidencias y discrepancias entre fuentes.`:'La cobertura se habilita a medida que se incorporan documentos de cada institución.'}</p><div class="coverage-strip">${coverage.map(s=>`<span class="source-mini ${s.count?'':'missing'}" title="${e(s.note)}"><i></i>${s.short}</span>`).join('')}</div><div class="panel-footer"><span>Una institución mencionada no equivale a una fuente directa.</span></div></article></section>${figCaption('Evolución: conflictos activos y latentes por mes en el historial de la empresa. Cobertura: qué instituciones tienen publicaciones incorporadas a esta cartera.','Base de reportes de la Defensoría 2012-2025; conectores de fuentes oficiales.','Historial hasta diciembre de 2025; fuentes hasta la última ejecución.')}`;}
function mediaPanel(){const m=state.payload.media;if(!m||!m.total)return '';const weeks=m.weekly||[],max=Math.max(1,...weeks.map(w=>w.total)),tags=['Medida de fuerza','Violencia','Seguridad','Ambiental','Diálogo y acuerdos','Estado de emergencia','Operación y producción','Contexto'],colors={'Medida de fuerza':'#c0794f','Violencia':'#a5483c','Seguridad':'#8a6d9e','Ambiental':'#3f8f8a','Diálogo y acuerdos':'#6f9d6a','Estado de emergencia':'#d0a24a','Operación y producción':'#7c8fa3','Contexto':'#c9d2c8'},bw=100/Math.max(weeks.length,1);const bars=weeks.map((w,i)=>{let y=100;return tags.filter(t=>w.counts[t]).map(t=>{const h=w.counts[t]/max*86;y-=h;return `<rect x="${i*bw+bw*.18}" y="${y}" width="${bw*.64}" height="${h}" fill="${colors[t]}" rx=".6"><title>${e(t)}: ${w.counts[t]} · semana del ${e(w.week)}</title></rect>`;}).join('');}).join('');const used=tags.filter(t=>weeks.some(w=>w.counts[t]));return `<section class="panel media-panel"><div class="panel-heading"><div><h2>${icon('activity')}Pulso de medios</h2><p class="panel-subtitle">${m.total} notas de ${m.outlets.length} medios en 120 días · ${m.feeds_ok}/${m.feeds} feeds respondieron · actualizado ${e(dateLabel(m.updated_at))}</p></div><span class="source-badge">Señal diaria entre reportes oficiales</span></div><div class="media-grid"><div class="media-chart"><svg viewBox="0 0 100 100" preserveAspectRatio="none" role="img" aria-label="Notas por semana">${bars}</svg><div class="chart-legend">${used.map(t=>`<span><i style="background:${colors[t]}"></i>${e(t)}</span>`).join('')}</div><p class="report-note">Notas por semana según la primera etiqueta. Medios: ${m.outlets.slice(0,6).map(([o,n])=>`${e(o)} (${n})`).join(', ')}.</p></div><div class="media-list">${m.items.slice(0,7).map(i=>`<a class="media-item" href="${e(safeURL(i.url))}" target="_blank" rel="noopener"><div class="signal-meta"><span class="source-badge">${e(i.outlet)}</span><span>${e(dateLabel(i.published))}</span>${i.tags.filter(t=>t!=='Contexto').map(t=>`<span class="media-tag" style="--tag:${colors[t]}">${e(t)}</span>`).join('')}${i.case_codes.length?`<span class="media-tag case">Caso ${e(i.case_codes.join(', '))}</span>`:''}</div><strong>${e(i.title)}</strong></a>`).join('')}</div></div><div class="panel-footer"><span>${e(m.method)} Una nota no se suma a los casos ni prueba un hecho: se contrasta con la ficha oficial.</span></div>${figCaption('Barras: notas por semana, coloreadas por su primer tema. Lista: las notas más recientes con su medio y el caso que mencionan.','RSS de El Comercio, La República, Andina y Google News (agrega RPP, Gestión, Infobae, Expreso y regionales).',`Ventana de 120 días hasta ${dateLabel(m.updated_at)}.`)}</section>`;}
function figCaption(what,source,cutoff){return `<dl class="fig-caption"><div><dt>Qué muestra</dt><dd>${e(what)}</dd></div><div><dt>Fuente</dt><dd>${e(source)}</dd></div><div><dt>Corte</dt><dd>${e(cutoff)}</dd></div></dl>`;}
function actorsSection(c){const a=c.actors||{};if(!a.primarios&&!a.secundarios&&!a.terciarios)return '';return `<section class="detail-section"><h3>Con quién gestionar</h3><dl class="actor-list">${[['primarios','Partes del conflicto (actores primarios)'],['secundarios','Intervienen (actores secundarios)'],['terciarios','Median o supervisan (actores terciarios)']].map(([k,l])=>a[k]?`<div><dt>${l}</dt><dd>${a[k].split(/,\s*(?![^()]*\))/).map(x=>`<span class="actor-chip">${e(x.trim().replace(/\.$/,''))}</span>`).join('')}</dd></div>`:'').join('')}</dl><p class="report-note">Tal como los nombra la ficha oficial de la Defensoría del ${e(periodLabel(state.payload.period))}.</p></section>`;}
function historyPanel(){const rows=state.payload.linked_history||[];if(!rows.length)return '';return `<section class="panel document-list"><div class="panel-heading"><div><h2>${icon('clock')}Historial de conflictos vinculados a ${e(state.payload.company.name)}</h2><p class="panel-subtitle">${rows.length} conflictos en los reportes de la Defensoría 2012-2025 · los que siguen activos sin cierre aparecen también en Alertas</p></div></div><div class="table-wrapper"><table class="case-table"><thead><tr><th>Conflicto</th><th>Distrito</th><th>Período</th><th>Último estado</th><th>Partes (actores primarios)</th></tr></thead><tbody>${rows.map(h=>`<tr><td><div class="case-name">${e(h.name)}</div>${h.provisional?'<div class="case-place">Registro provisional de la base</div>':''}</td><td>${e(h.district||'s/d')}</td><td>${e(h.first_period||'')} – ${e(h.last_period||'')}</td><td>${e(h.last_status||'s/d')}</td><td>${e((h.actors||{}).primarios||'s/d')}</td></tr>`).join('')}</tbody></table></div><div class="panel-footer"><span>Fuente: base de tesis construida con los reportes mensuales de la Defensoría. Un conflicto se vincula cuando la empresa figura en su denominación, descripción o actores.</span></div></section>`;}
function summaryView(){return metrics()+alertStrip()+`<section class="overview-grid">${mapPanel()}${signals()}</section>`+phaseOverview()+mediaPanel()+lowerPanels()+note('Las cifras corresponden al corpus y a la cartera seleccionada. Las fases no documentadas permanecen sin clasificación.');}
function note(message){return `<div class="section-note">${icon('shield')}<span>${e(message)}</span></div>`;}
function territoryView(){const p=state.payload,g=state.geo||p.geography,points=p.cases.filter(c=>validCoordinates(c.coordinates));return `<section class="territory-overview">${mapPanel(true)}<aside class="panel territory-side"><h3>Tu huella territorial</h3><div class="territory-stat"><strong>${new Set(p.cases.map(c=>c.region).filter(Boolean)).size}</strong><small>Regiones documentadas</small></div><div class="territory-stat"><strong>${points.length}</strong><small>Casos con referencia geográfica</small></div><div class="territory-stat"><strong>${collection(g.operations).features.length}</strong><small>Geometrías de operaciones</small></div><div class="territory-stat"><strong>${collection(g.roads).features.length}</strong><small>Tramos viales incorporados</small></div><p class="territory-description">Las capas conservan su fecha y precisión. Una comunidad, concesión, pozo u operación son unidades distintas. Una relación espacial no acredita afectación ni responsabilidad.</p>${(g.metadata||[]).map(m=>`<p class="territory-description">${e(typeof m==='string'?m:[m.name||m.title,m.date,m.note].filter(Boolean).join(' · '))}</p>`).join('')}</aside></section>`+mapReadingPanel()+note('Activa las capas disponibles para explorar el contexto. Las capas sin geometrías incorporadas permanecen deshabilitadas.');}
function caseRows(cases){return cases.map(c=>`<tr data-case="${e(c.id)}" tabindex="0" role="button" aria-label="Abrir caso ${e(c.name)}"><td><div class="case-name">${e(c.name)}</div><div class="case-place">${e([c.district,c.province,c.region].filter(Boolean).join(' · ')||'Territorio no informado')}</div></td><td>${statusBadge(c.status)}</td><td>${e(c.phase||'Sin fase documentada')}</td><td>${(c.source_ids||[]).length}<span class="visually-hidden"> fuentes relacionadas</span></td><td>${icon('arrow')}</td></tr>`).join('');}
function casesView(){const cases=filterCases(state.payload.cases,state.query,state.status);return `<section class="${state.selectedCase?'case-layout':''}"><div class="panel"><div class="filter-row"><label class="search-field">${icon('search')}<span class="visually-hidden">Filtrar casos de la cartera</span><input id="case-search" type="search" placeholder="Buscar en tu cartera" value="${e(state.query)}"></label><label><span class="visually-hidden">Estado reportado</span><select id="case-status"><option value="">Todos los estados</option><option value="active" ${state.status==='active'?'selected':''}>Activo</option><option value="latent" ${state.status==='latent'?'selected':''}>Latente</option><option value="unknown" ${state.status==='unknown'?'selected':''}>Sin clasificar</option></select></label><span class="filter-count">${cases.length} casos</span></div><div class="table-wrapper"><table class="case-table"><thead><tr><th>Caso / territorio</th><th>Estado</th><th>Fase reportada</th><th>Fuentes</th><th><span class="visually-hidden">Abrir</span></th></tr></thead><tbody>${caseRows(cases)}</tbody></table></div>${cases.length?'':empty('Sin casos en esta selección','Prueba otro filtro o consulta un período con documentación disponible.')}</div>${state.selectedCase?caseDetail(state.selectedCase):''}</section>`+historyPanel()+stakeholdersPanel()+note('Las fichas distinguen la situación reportada de los compromisos y fechas que requieren verificación posterior.');}
function sourceById(id){return state.payload.sources.find(s=>String(s.id)===String(id));}
function sourceLink(source,label){if(!source)return '';const name=label||source.institution||source.title,url=safeURL(source.url||source.pdf_url);return url==='#'?`<span class="timeline-source">${e(name)} · referencia local</span>`:`<a href="${e(url)}" target="_blank" rel="noopener" class="timeline-source">${e(name)} ${icon('external')}</a>`;}
function pageLink(item){return item&&item.pdf_url&&item.page?`<a href="${e(safeURL(item.pdf_url))}" target="_blank" rel="noopener" class="timeline-source page-link">Ver pasaje · p. ${e(item.page)} del PDF ${icon('report')}</a>`:'';}
function commitmentCards(c){const items=c.commitments||[];if(!items.length)return '';return `<section class="detail-section"><h3>Compromisos y agenda reportada</h3><div class="commitment-list">${items.map(item=>`<div class="commitment-item"><strong>${e(item.text)}</strong><span>${icon('calendar')}${e(item.due_date?dateLabel(item.due_date):item.due_precision||'Sin plazo especificado')}</span><small>${e(item.responsible||'Responsable no individualizado')}</small><p>${e(item.reported_status||'Estado posterior no verificado')}</p></div>`).join('')}</div></section>`;}
function caseDetail(id){const c=state.payload.cases.find(c=>String(c.id)===String(id));if(!c)return '';const events=[...(c.events||[])].sort((a,b)=>String(b.date||b.period||'').localeCompare(String(a.date||a.period||'')));const sources=(c.source_ids||[]).map(sourceById).filter(Boolean);return `<article class="panel case-detail" aria-label="Ficha del caso"><div class="detail-topline">${statusBadge(c.status)}<button class="icon-button" data-close-case aria-label="Cerrar ficha">${icon('close')}</button></div><h2 class="detail-title">${e(c.name)}</h2><p class="detail-region">${icon('pin')}${e([c.district,c.province,c.region].filter(Boolean).join(' · ')||'Ubicación no informada')}</p><div class="detail-phase"><div>${icon('activity')}</div><div><strong>${e(c.phase||'Sin fase documentada')}</strong><small>${e(c.phase_basis||'La fase se conserva según su fuente; no se infiere del número de eventos.')}</small></div></div><section class="detail-section"><h3>Contexto documentado</h3><p>${e(c.summary||'Consulta las fuentes vinculadas para revisar la descripción completa del caso.')}</p></section>${detailList('Demandas reportadas',c.demands)}${commitmentCards(c)}${c.historical_observations?.length?`<section class="detail-section"><h3>Trayectoria mensual</h3><p class="report-note">${e(c.historical_link_note)}</p><div class="history-months">${c.historical_observations.slice(-12).map(o=>`<span class="history-month"><small>${e(periodLabel(o.period,true))}</small><strong>${e(o.status||'Sin estado')}</strong></span>`).join('')}</div><p class="report-note">${c.historical_observations.length} observaciones en la base; no se prolonga el último estado hasta hoy.</p></section>`:''}${actorsSection(c)}${swimlane(c)}${territorySection(c)}${contrastSection(c,sources)}<section class="detail-section"><h3>Línea de tiempo</h3>${events.length?`<div class="timeline">${events.map(event=>`<div class="timeline-item"><div class="timeline-date">${e(dateLabel(event.date||event.period))}</div><h4 class="timeline-title">${e(event.title||'Observación documental')}</h4><p class="timeline-summary">${event.literal?'«'+e(event.summary)+'»':e(event.summary||'')}</p>${sourceLink(sourceById(event.source_id))}${pageLink(event)}</div>`).join('')}</div>`:'<p>Aún no hay acontecimientos fechados incorporados para este caso.</p>'}</section><section class="detail-section"><h3>Fuentes vinculadas</h3>${sources.length?sources.map(s=>`<p>${sourceLink(s,s.title||s.institution)}</p>`).join(''):'<p>Vinculación documental pendiente de completar.</p>'}</section><section class="detail-section"><button class="button button-quiet" id="interpret-button">${icon('sparkles')}Interpretar esta selección</button><p class="report-note">${!STATIC&&state.payload.coverage.ai_available?'Groq lee la ficha y los pasajes PDF del caso. Cada afirmación debe traer una cita literal o se descarta.':'Sin clave de IA en esta versión: se muestra la última lectura generada con Groq, con fecha y modelo.'}</p><div id="interpret-result"></div></section></article>`;}
function detailList(title,items){return Array.isArray(items)&&items.length?`<section class="detail-section"><h3>${title}</h3><ul>${items.map(item=>`<li>${e(text(item))}</li>`).join('')}</ul></section>`:'';}
function relatedSignals(){const news=state.payload.related_news||state.payload.supplementary?.newscases||[];if(!news.length)return '';return `<section class="panel document-list"><div class="panel-heading"><div><h2>${icon('activity')}Otras señales de la operación</h2><p class="panel-subtitle">Publicaciones complementarias · no se suman a los casos de la cartera</p></div></div><div class="related-signals">${news.map(s=>`<article class="related-signal"><div class="signal-meta"><span class="source-badge">${e(s.institution||'Fuente complementaria')}</span><span>${e(dateLabel(s.date))}</span></div><h3>${e(s.title||'Publicación de seguimiento')}</h3><p>${e(s.claim||s.summary||'Consulta la publicación original para revisar su alcance.')}</p>${s.quote?`<blockquote class="literal-quote">«${e(s.quote)}»</blockquote>`:''}${s.url?sourceLink(s,'Consultar fuente original'):''}${pageLink(s)}</article>`).join('')}</div><div class="panel-footer"><span>Estas señales conservan su unidad documental y no se fusionan automáticamente con un conflicto existente.</span></div></section>`;}
function contrastSection(c,sources){const related=c.related_news||(state.payload.related_news||[]).filter(n=>n.case_id===c.id||(n.case_ids||[]).includes(c.id));const evidence=[...sources.filter(s=>s.claim||s.summary),...related];if(!evidence.length)return '';return `<section class="detail-section"><h3>Lecturas entre fuentes</h3>${evidence.map(s=>`<article class="contrast-card"><div><strong>${e(s.institution||'Fuente documental')}</strong><small>${e(dateLabel(s.date))}</small></div><p>${e(s.claim||s.summary||s.title)}</p>${sourceLink(s,s.title||'Consultar publicación')}</article>`).join('')}<p class="report-note">Publicación y acontecimiento pueden tener fechas distintas. El contraste conserva las versiones atribuidas a cada fuente.</p></section>`;}
function sourcesView(){const coverage=sourceCoverage(state.payload);const sourceIds=new Set(coverage.flatMap(row=>state.payload.sources.filter(s=>row.match.some(k=>normalize(s.institution).includes(k))).map(s=>s.id)));const extra=[...new Set(state.payload.sources.filter(s=>!sourceIds.has(s.id)).map(s=>s.institution).filter(Boolean))].map(name=>({name,short:name.slice(0,6),count:state.payload.sources.filter(s=>s.institution===name).length,note:'Documentos incorporados al corpus.'}));return `<section class="source-grid">${[...coverage,...extra].map(s=>`<article class="source-card ${s.count?'':'missing'}"><div class="source-card-top"><span class="source-initials">${e(s.short)}</span><span class="source-badge ${s.count?'':'pending'}">${s.count?'Fuente directa':'Sin corpus directo'}</span></div><h3>${e(s.name)}</h3><p>${e(s.note)}</p><div class="source-card-footer"><span>${s.count} documentos incorporados</span>${s.count?icon('check'):icon('clock')}</div></article>`).join('')}</section><section class="panel document-list"><div class="panel-heading"><div><h2>${icon('sources')}Biblioteca de la cartera</h2><p class="panel-subtitle">Documentos que sustentan esta selección</p></div><span class="filter-count">${state.payload.sources.length} fuentes</span></div>${state.payload.sources.map(s=>`<a class="document-row" href="${e(safeURL(s.url||s.pdf_url))}" target="_blank" rel="noopener">${icon('report')}<span class="document-row-text"><strong>${e(s.title||'Documento sin título')}</strong><small>${e(s.institution||'Institución no informada')} · ${e(dateLabel(s.date))}${s.kind?' · '+e(s.kind):''}</small></span>${icon('external')}</a>`).join('')||empty('Biblioteca sin documentos','Aún no se han incorporado documentos vinculados a esta cartera.')}</section>`+lensPanel()+stateActionsPanel()+relatedSignals()+note('La mención de una institución como actor en un reporte no equivale a haber incorporado una publicación de esa institución.');}
function reportsView(){const p=state.payload;return `<section class="report-grid"><article class="panel report-preview"><div class="report-masthead"><span class="report-brand">PulsoTerritorial</span><small>INTELIGENCIA TERRITORIAL</small></div><span class="eyebrow">REPORTE EJECUTIVO · ${e(periodLabel(p.period))}</span><h2>Una lectura del territorio.<br>Un punto de partida<br>para decidir.</h2><p class="report-subtitle">${e(p.company.name||'Cartera seleccionada')} · ${e(p.company.sector||'Seguimiento socioambiental')}</p><div class="report-divider"></div><p class="report-excerpt">${e(p.insights[0]?.text||p.cases[0]?.summary||'Síntesis documental de los casos, su evolución y las fuentes incorporadas para el período seleccionado.')}</p><div class="report-numbers"><span><strong>${number(p.summary.cases)}</strong><small>Casos en cartera</small></span><span><strong>${number(p.summary.sources)}</strong><small>Fuentes documentales</small></span><span><strong>${number(p.summary.active)}</strong><small>Activos reportados</small></span></div><div class="report-bottom">Basado en evidencia pública · Alcance y limitaciones incluidos en el reporte</div></article><aside class="panel report-options"><h3>Reporte mensual de tu cartera</h3><p>Comparte una lectura ordenada del período, con acceso a la evidencia original.</p>${['Resumen ejecutivo y cobertura','Casos, estados y contexto territorial','Acontecimientos y compromisos reportados','Fuentes, discrepancias y limitaciones'].map(label=>`<div class="report-option-row"><span>${label}</span>${icon('check')}</div>`).join('')}<div class="report-actions"><a class="button button-primary" href="${reportURL()}" target="_blank" rel="noopener">${icon('report')}Abrir reporte mensual</a><a class="button button-secondary" href="${reportURL()}" download="PulsoTerritorial_${e(p.period||'reporte')}.html">${icon('download')}Descargar reporte HTML</a><button class="button button-quiet" id="print-report">${icon('external')}Abrir para guardar como PDF</button></div><p class="report-note">El reporte es generado desde la cartera y el período seleccionado. El envío por correo requiere una integración adicional.</p></aside></section>`;}

function destroyMaps(){for(const entry of state.maps){try{entry.map.remove();}catch{}}state.maps=[];}
function render(){if(!state.payload)return;destroyMaps();const p=state.payload;$('#breadcrumb-company').textContent=p.company.name||'Cartera seleccionada';$('#account-sector').textContent=p.company.name||p.company.sector|| (state.company==='hidrocarburos'?'Cartera energética':'Cartera minera');$('#account-avatar').textContent=p.company.initials||'PT';const accountNote=$('#account-button small');if(accountNote)accountNote.textContent=state.session?state.session.user:'Sesión de analista';$('#nav-case-count').textContent=String(p.summary.cases);const alertNode=$('#nav-alert-count');if(alertNode)alertNode.textContent=String((p.alerts||[]).length);$('#coverage-label').textContent=p.coverage.label||`${p.sources.length} ${p.sources.length===1?'fuente incorporada':'fuentes incorporadas'}`;document.querySelectorAll('#main-nav a').forEach(a=>{const active=a.dataset.view===state.view;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});const views={pais:nationalView,alertas:alertsView,sistema:systemView,resumen:summaryView,territorio:territoryView,conflictos:casesView,fuentes:sourcesView,reportes:reportsView};$('#content').innerHTML=`<div class="view-entry">${heading()}${views[state.view]()}</div>`;if($('#territory-map'))initMap();if($('#national-map'))initNationalMap();}

function fallbackMap(container,reason){const points=state.payload.cases.filter(c=>validCoordinates(c.coordinates));if(!points.length){container.innerHTML=`<div class="map-fallback">${icon('map')}<strong>Cartografía no disponible</strong><p>${e(reason)} Las fichas y fuentes siguen disponibles.</p></div>`;return;}const lons=points.map(c=>c.coordinates[0]),lats=points.map(c=>c.coordinates[1]),minX=Math.min(...lons)-.15,maxX=Math.max(...lons)+.15,minY=Math.min(...lats)-.15,maxY=Math.max(...lats)+.15;container.innerHTML=`<div class="map-fallback"><svg viewBox="0 0 560 230" style="width:100%;height:210px" role="img" aria-label="Referencia esquemática de ubicaciones documentadas"><rect width="560" height="230" fill="#edf2e7"/>${[60,120,180].map(y=>`<line x1="20" y1="${y}" x2="540" y2="${y}" stroke="#dce5d3" stroke-dasharray="4 7"/>`).join('')}${points.map((c,i)=>{const x=50+(c.coordinates[0]-minX)/(maxX-minX)*460,y=205-(c.coordinates[1]-minY)/(maxY-minY)*180;return `<circle cx="${x}" cy="${y}" r="5" fill="#b39b69" stroke="white" stroke-width="2"/><text x="${x+9}" y="${y-5}" font-size="9" fill="#79916b">${e((c.name||'Caso').slice(0,38))}</text>`;}).join('')}</svg><strong>Referencia esquemática</strong><p>${e(reason)} Esta vista de respaldo no representa un mapa 3D.</p></div>`;}
function initMap(){const container=$('#territory-map');if(!container)return;if(!window.maplibregl){fallbackMap(container,'No se pudo cargar el visor cartográfico.');return;}const geo=state.geo||state.payload.geography||{};const points=state.payload.cases.filter(c=>validCoordinates(c.coordinates));try{container.innerHTML='';const map=new window.maplibregl.Map({container,style:geo.map_style_url||geo.map_style||'https://tiles.openfreemap.org/styles/positron',center:geo.center||points[0]?.coordinates||[-75,-10],zoom:Number(geo.zoom)|| (points.length?7:4.2),pitch:state.threeD?52:0,bearing:state.threeD?-12:0,attributionControl:true,maxPitch:75});const entry={map,markers:[],layers:{}};state.maps.push(entry);map.addControl(new window.maplibregl.NavigationControl({visualizePitch:true}),'top-right');map.addControl(new window.maplibregl.ScaleControl({maxWidth:80,unit:'metric'}),'bottom-right');map.on('load',()=>{addSatellite(map);if(geo.terrain_url){try{map.addSource('pulso-terrain',{type:'raster-dem',...(geo.terrain_url.includes('{z}')?{tiles:[geo.terrain_url]}:{url:geo.terrain_url}),encoding:geo.terrain_encoding||'terrarium',tileSize:512,maxzoom:14,attribution:geo.terrain_attribution||'Mapterhorn · Copernicus GLO-30'});map.addLayer({id:'pulso-hillshade',type:'hillshade',source:'pulso-terrain',paint:{'hillshade-exaggeration':.35,'hillshade-shadow-color':'#456258','hillshade-highlight-color':'#faf8ef'}},map.getStyle().layers.find(l=>l.type==='symbol')?.id);if(state.threeD)map.setTerrain({source:'pulso-terrain',exaggeration:1.25});}catch{}}for(const [key,color,type] of [['boundary','#72936a','polygon'],['roads','#c4a671','line'],['operations','#588c8e','mixed'],['communities','#bd9b6e','mixed'],['wells','#829b70','mixed'],...geoperuLayers().map(l=>[l.key,l.color,'mixed'])]){const data=collection(geo[key]||geoperuLayers().find(l=>l.key===key)?.data);if(!data.features.length)continue;try{map.addSource(`pulso-${key}`,{type:'geojson',data});const ids=[];if(type==='polygon'||type==='mixed'){const id=`pulso-${key}-fill`;map.addLayer({id,type:'fill',source:`pulso-${key}`,filter:['==',['geometry-type'],'Polygon'],paint:{'fill-color':color,'fill-opacity':key==='boundary'?.07:.19}});ids.push(id);}const lineId=`pulso-${key}-line`;map.addLayer({id:lineId,type:'line',source:`pulso-${key}`,filter:['in',['geometry-type'],['literal',['LineString','Polygon']]],paint:{'line-color':color,'line-width':key==='roads'?2:1.2,'line-opacity':.75}});ids.push(lineId);if(type==='mixed'){const id=`pulso-${key}-point`;map.addLayer({id,type:'circle',source:`pulso-${key}`,filter:['==',['geometry-type'],'Point'],paint:{'circle-radius':4,'circle-color':color,'circle-stroke-color':'white','circle-stroke-width':1.5}});ids.push(id);}entry.layers[key]=ids;const checked=$(`[data-layer="${key}"]`)?.checked;ids.forEach(id=>map.setLayoutProperty(id,'visibility',checked?'visible':'none'));}catch{}}addHistoryLayer(map,entry,geo);for(const group of groupCaseCoordinates(points)){const c=group.cases[0],multiple=group.cases.length>1;const button=document.createElement('button');button.className=`case-marker ${statusClass(c.status)==='latent'?'latent':''} ${multiple?'group-marker':''}`;button.type='button';button.textContent=multiple?String(group.cases.length):'';button.setAttribute('aria-label',multiple?`${group.cases.length} casos en una misma referencia administrativa`: `${c.name}. ${c.coordinate_precision||'Precisión no informada'}`);const popupHTML=multiple?`<strong>${group.cases.length} casos · misma referencia</strong><small>El punto administrativo se conserva sin desplazar ubicaciones.</small>${group.cases.map(item=>`<button class="map-popup-case" data-case="${e(item.id)}">${e(item.name)}</button>`).join('')}`:`<strong>${e(c.name)}</strong>${e([c.district,c.region].filter(Boolean).join(' · '))}<small>${e(c.coordinate_precision||'Precisión no informada')}</small>`;const popup=new window.maplibregl.Popup({offset:16,closeButton:multiple}).setHTML(popupHTML);const marker=new window.maplibregl.Marker({element:button}).setLngLat(group.coordinates).setPopup(popup).addTo(map);if(!multiple){button.addEventListener('mouseenter',()=>{if(!popup.isOpen())marker.togglePopup();});button.addEventListener('mouseleave',()=>{if(popup.isOpen())marker.togglePopup();});button.addEventListener('click',()=>openCase(c.id));}entry.markers.push(marker);}if(points.length>1&&!geo.zoom){const bounds=new window.maplibregl.LngLatBounds();points.forEach(c=>bounds.extend(c.coordinates));map.fitBounds(bounds,{padding:{top:80,bottom:65,left:150,right:65},maxZoom:9,pitch:state.threeD?52:0,duration:0});}});let warned=false;map.on('error',event=>{if(!warned){warned=true;const noteNode=container.closest('.panel')?.querySelector('.map-attribution-note span');if(noteNode)noteNode.textContent+=' Algunas capas cartográficas no se pudieron cargar.';}});}catch{fallbackMap(container,'El navegador no pudo inicializar la vista cartográfica.');}}

async function loadPortfolio(){const requestId=++state.requestId;destroyMaps();state.payload=null;state.geo=null;$('#content').innerHTML='<div class="loading-state"><div class="loader"></div>Conectando territorio y evidencia…</div>';const params=new URLSearchParams({company:state.company});if(state.period)params.set('period',state.period);try{const response=await fetch(apiURL('portfolio',Object.fromEntries(params)),{headers:{Accept:'application/json'}});if(!response.ok)throw Error(`La biblioteca respondió ${response.status}.`);const data=normalizePortfolio(await response.json());if(requestId!==state.requestId)return;state.payload=data;state.period=data.period;state.geo=data.geography;state.selectedCase=null;render();try{const geoResponse=await fetch(apiURL('geography',{company:state.company}),{headers:{Accept:'application/json'}});if(geoResponse.ok){const geo=await geoResponse.json();if(requestId===state.requestId){state.geo=geo.geography||geo;if(['resumen','territorio'].includes(state.view))render();}}}catch{/* La cartera sigue disponible aunque falten capas. */}}catch(error){if(requestId!==state.requestId)return;$('#content').innerHTML=`<div class="error-notice"><strong>No pudimos abrir la cartera.</strong><br>${e(error.message)} Comprueba que el servicio local esté funcionando.<br><button id="retry-button" class="button button-secondary" style="margin-top:15px">Volver a intentar</button></div>`;}}
function openCase(id){if(!id)return;state.selectedCase=String(id);state.view='conflictos';history.replaceState(null,'','#conflictos');render();setTimeout(()=>$('.case-detail')?.scrollIntoView({behavior:'smooth',block:'nearest'}),30);}
function navigate(){const view=location.hash.slice(1)||'resumen';state.view=viewTitles[view]?view:'resumen';$('.sidebar')?.classList.remove('open');if(state.payload)render();}
async function refresh(){const button=$('#refresh-button');if(STATIC){toast('La versión pública se regenera cada día con GitHub Actions. La revisión manual de fuentes está disponible en la instalación local.');return;}button.disabled=true;button.innerHTML=`${icon('refresh')}Revisando publicaciones…`;try{const response=await fetch('/api/refresh',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({company:state.company,period:state.period})});let result={};try{result=await response.json();}catch{}if(!response.ok)throw Error(result.error||result.detail||`Respuesta ${response.status}`);toast(result.message||'Revisión de fuentes finalizada. Consulta la cobertura actualizada.');await loadPortfolio();}catch(error){toast(`No se completó la actualización. ${error.message}`);}finally{button.disabled=false;button.innerHTML=`${icon('refresh')}Actualizar monitoreo`;}}
async function interpret(){const button=$('#interpret-button'),resultNode=$('#interpret-result');if(!button||!resultNode)return;button.disabled=true;button.textContent='Interpretando evidencia…';try{const saved=STATIC||!state.payload.coverage.ai_available?await savedReading(state.selectedCase):null;const response=saved?null:await fetch('/api/interpret',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({company:state.company,period:state.period,case_id:state.selectedCase,provider:state.payload.coverage.ai_provider||'groq'})});const result=saved||await response.json();if(response&&!response.ok)throw Error(result.error||result.detail||`Respuesta ${response.status}`);const records=result.records||result.analysis?.records||[];const origin=saved?`Lectura guardada · ${e(result.provider||'IA')} ${e(result.model||'')} · ${e(dateLabel(result.generated_at))}`:`Interpretación asistida · ${e(result.model||'')}`;resultNode.innerHTML=`<div class="ai-result"><div class="ai-label">${origin} · ${records.length} afirmaciones con cita literal · ${(result.rejected||[]).length} descartadas por el validador</div>${records.length?records.map(record=>`<p>${e(record.claim||record.text||record.summary||text(record))}</p>${record.quote?`<blockquote>“${e(record.quote)}” <small>· ${e(sourceById(record.document_id)?.institution||record.document_id)}${record.method==='pdf_pypdf'?', p. '+e(record.page):''}</small></blockquote>`:''}`).join(''):`<p>${e(result.message||'No se obtuvo una interpretación con evidencia suficiente.')}</p>`}</div>`;}catch(error){resultNode.innerHTML=`<p class="report-note">${e(error.message)}</p>`;}finally{button.disabled=false;button.innerHTML=`${icon('sparkles')}Interpretar esta selección`;}}

// Monitoreo: alertas, línea de tiempo por actor, contexto territorial y estado del sistema.
const LANE_COLORS={'Defensoría':'#167b70','Ejecutivo':'#2563b9','Fiscalización y agua':'#3f8f8a','Policía':'#8a6d9e','Empresa':'#b58438','Prensa':'#c0794f'};
const SEVERITY_LABEL={alta:'Alta',media:'Media',baja:'Baja'};

function eventDay(event){const value=String(event.date||event.period||'');return value.length===7?value+'-15':value.slice(0,10);}

function alertCard(a){return `<article class="alert-card ${e(a.severity)}"><div class="alert-top"><span class="alert-severity ${e(a.severity)}">${e(SEVERITY_LABEL[a.severity]||a.severity)}</span><span>${e(dateLabel(a.date))}</span>${a.case_id?`<button class="text-link" data-open-alert-case="${e(a.case_id)}">${e(a.case_name||a.case_id)} ${icon('arrow')}</button>`:'<span class="alert-scope">Entorno de la operación</span>'}</div><h3>${e(a.title)}</h3><p>${e(a.detail)}</p>${a.evidence?.length?`<ul class="alert-evidence">${a.evidence.map(ev=>`<li><a href="${e(safeURL(ev.url))}" target="_blank" rel="noopener">${e(ev.title||'Fuente')}</a> <small>${e(ev.institution||'')} · ${e(dateLabel(ev.date))}</small></li>`).join('')}</ul>`:''}${a.evidence_status==='sin_enlace_incorporado'?'<p class="alert-rule">Sin enlace documental incorporado. Esta señal requiere verificar su procedencia antes de usarla en un reporte.</p>':a.evidence_status==='parcial'?'<p class="alert-rule">Evidencia parcial: faltan referencias por incorporar.</p>':''}<p class="alert-rule">${icon('info')}Regla: ${e(a.rule_text)}</p></article>`;}

function alertStrip(){const alerts=state.payload.alerts||[];if(!alerts.length)return '';const s=state.payload.alert_summary||{};return `<section class="panel alert-strip"><div class="panel-heading"><div><h2>${icon('shield')}Alertas tempranas</h2><p class="panel-subtitle">${alerts.length} activas · ${s.alta||0} altas · ${s.media||0} medias · ${s.baja||0} bajas</p></div><a class="text-link" href="#alertas">Ver todas ${icon('arrow')}</a></div><div class="alert-strip-grid">${alerts.slice(0,3).map(alertCard).join('')}</div></section>`;}

function alertsView(){const alerts=state.payload.alerts||[];const rules=state.payload.alert_rules||{};return `${alerts.length?`<section class="alert-list">${alerts.map(alertCard).join('')}</section>`:empty('Sin alertas activas','Ninguna regla se activó con las fuentes incorporadas al corte. No equivale a ausencia de riesgo.')}<section class="panel rules-panel"><div class="panel-heading"><div><h2>${icon('info')}Cómo se generan</h2><p class="panel-subtitle">Reglas explícitas y auditables · ninguna alerta es una predicción</p></div></div><dl class="rules-list">${Object.entries(rules).map(([k,v])=>`<div><dt>${e(k)}</dt><dd>${e(v)}</dd></div>`).join('')}</dl></section>`;}

function swimlane(c){const lanes=state.payload.lanes||Object.keys(LANE_COLORS);const events=(c.events||[]).filter(ev=>eventDay(ev));const hist=(c.historical_observations||[]).map(o=>({period:o.period,status:o.status,lane:'Defensoría',history:true}));const days=[...events.map(eventDay),...hist.map(h=>h.period+'-15')].map(d=>new Date(d+'T00:00:00')).filter(d=>!isNaN(d));if(!days.length)return '';let min=new Date(Math.min(...days)),max=new Date(Math.max(...days,Date.now()));const span=Math.max(max-min,86400000*60);min=new Date(min-span*.03);max=new Date(+max+span*.03);const W=1000,L=150,R=16,rowH=34,top=18,H=top+lanes.length*rowH+26;const x=d=>L+(new Date(d+'T00:00:00')-min)/(max-min)*(W-L-R);const ticks=[];const t=new Date(min.getFullYear(),min.getMonth(),1);const step=Math.max(1,Math.round((max-min)/86400000/30/8));while(t<=max){if(t>=min)ticks.push(new Date(t));t.setMonth(t.getMonth()+step);}
const months={};events.forEach((ev,i)=>{const key=eventDay(ev).slice(0,7);(months[key]=months[key]||[]).push(i);});
return `<section class="detail-section"><h3>Línea de tiempo por actor</h3><p class="report-note">Cada punto es una publicación. Haz clic para ver qué reportó cada actor ese mes. Los cuadros grises son el estado mensual en la base histórica de la Defensoría.</p><div class="swimlane-wrap"><svg class="swimlane" viewBox="0 0 ${W} ${H}" role="group" aria-label="Línea de tiempo del caso por tipo de actor">${lanes.map((lane,r)=>`<g><text x="0" y="${top+r*rowH+rowH/2+4}" class="lane-label">${e(lane)}</text><line x1="${L}" x2="${W-R}" y1="${top+r*rowH+rowH/2}" y2="${top+r*rowH+rowH/2}" class="lane-line"/></g>`).join('')}${ticks.map(d=>{const iso=d.toISOString().slice(0,10);return `<g><line x1="${x(iso)}" x2="${x(iso)}" y1="${top-6}" y2="${H-22}" class="tick-line"/><text x="${x(iso)}" y="${H-6}" class="tick-label" text-anchor="middle">${e(periodLabel(iso.slice(0,7),true))}</text></g>`;}).join('')}<line x1="${x(new Date().toISOString().slice(0,10))}" x2="${x(new Date().toISOString().slice(0,10))}" y1="${top-8}" y2="${H-22}" class="today-line"/>${hist.map(h=>`<rect x="${x(h.period+'-15')-3}" y="${top+rowH/2-3}" width="6" height="6" class="history-mark"><title>${e(h.period)} · ${e(h.status||'sin estado')}</title></rect>`).join('')}${events.map((ev,i)=>{const r=Math.max(0,lanes.indexOf(ev.lane));const key=eventDay(ev).slice(0,7);return `<circle tabindex="0" role="button" data-lane-month="${e(key)}" cx="${x(eventDay(ev))}" cy="${top+r*rowH+rowH/2}" r="${ev.literal?7:5.5}" fill="${LANE_COLORS[ev.lane]||'#777'}" class="lane-dot ${ev.literal?'literal':''}"><title>${e(ev.lane)} · ${e(dateLabel(ev.date||ev.period))} · ${e(ev.title||'')}</title></circle>`;}).join('')}</svg></div><div class="lane-legend">${lanes.map(l=>`<span><i style="background:${LANE_COLORS[l]}"></i>${e(l)} (${events.filter(ev=>ev.lane===l).length})</span>`).join('')}<span><i class="ring"></i>Cita literal con página</span></div><div id="lane-detail" class="lane-detail"><p class="report-note">Selecciona un punto para ver el mes.</p></div></section>`;}

function laneMonthDetail(month){const c=state.payload.cases.find(c=>String(c.id)===String(state.selectedCase));if(!c)return;const events=(c.events||[]).filter(ev=>eventDay(ev).slice(0,7)===month);const lanes=state.payload.lanes||Object.keys(LANE_COLORS);const lenses=state.payload.lenses||{};const node=$('#lane-detail');if(!node)return;node.innerHTML=`<h4>${e(periodLabel(month))} · ${events.length} publicación(es)</h4>${lanes.filter(l=>events.some(ev=>ev.lane===l)).map(l=>`<div class="lane-group"><strong style="color:${LANE_COLORS[l]}">${e(l)}</strong>${events.filter(ev=>ev.lane===l).map(ev=>{const src=sourceById(ev.source_id);const lens=lenses[ev.institution_key]?.lens;return `<div class="lane-item"><div class="signal-meta"><span class="source-badge">${e(src?.institution||ev.lane)}</span><span>${e(dateLabel(ev.date||ev.period))}</span>${(ev.tags||[]).filter(t=>t!=='Contexto').map(t=>`<span class="media-tag">${e(t)}</span>`).join('')}${ev.automatic?'<span class="media-tag case">Extracción automática</span>':''}</div><p class="lane-title">${e(ev.title||'')}</p><p>${ev.literal?'«'+e(ev.summary)+'»':e(ev.summary||'')}</p>${sourceLink(src)}${pageLink(ev)}${lens?`<p class="alert-rule">${icon('info')}Encuadre de la fuente: ${e(lens)}</p>`:''}</div>`;}).join('')}</div>`).join('')}`;node.scrollIntoView({block:'nearest',behavior:'smooth'});}

function territorySection(c){const rows=c.territory||[];if(!rows.length)return '';return `<section class="detail-section"><h3>Contexto territorial · GEOPERÚ</h3><dl class="territory-rows">${rows.map(r=>`<div><dt>${e(r.label)}</dt><dd>${e(r.value)}</dd></div>`).join('')}</dl><p class="report-note">Base: ${e(rows[0].basis)}. Capas oficiales consultadas por ArcGIS REST del geoservidor del MINAM. La cercanía no acredita afectación.</p></section>`;}

function lensPanel(){const lenses=state.payload.lenses||{};const counts={};(state.payload.cases||[]).forEach(c=>(c.events||[]).forEach(ev=>{counts[ev.lane]=(counts[ev.lane]||0)+1;}));(state.payload.state_actions||[]).forEach(a=>{counts[a.lane]=(counts[a.lane]||0)+1;});return `<section class="panel lens-panel"><div class="panel-heading"><div><h2>${icon('sources')}Cada fuente mira desde su función</h2><p class="panel-subtitle">Por eso se contrastan: el encuadre de cada actor explica qué destaca y qué omite</p></div></div><div class="lens-grid">${Object.values(lenses).map(l=>`<div class="lens-card"><strong>${e(l.institution)}</strong><small>${e(l.role)}</small><p>${e(l.lens)}</p></div>`).join('')}</div><div class="panel-footer"><span>Publicaciones por tipo de actor en esta cartera: ${Object.entries(counts).map(([k,v])=>`${e(k)} ${v}`).join(' · ')}</span></div></section>`;}

function stateActionsPanel(){const items=state.payload.state_actions||[];if(!items.length)return '';return `<section class="panel document-list"><div class="panel-heading"><div><h2>${icon('activity')}Actuación del Estado en el territorio</h2><p class="panel-subtitle">${items.length} notas, comunicados y pasajes de informes oficiales sobre la operación y su entorno que no nombran un caso de la cartera</p></div></div>${items.slice(0,25).map(i=>`<a class="document-row" href="${e(safeURL(i.page?i.url+'#page='+i.page:i.url))}" target="_blank" rel="noopener">${icon('report')}<span class="document-row-text"><strong>${e(i.title)}${i.page?` · p. ${e(i.page)}`:''}</strong><small>${e(i.institution)} · ${e(i.lane)} · ${e(dateLabel(i.date||i.period))}${(i.tags||[]).filter(t=>t!=='Contexto').map(t=>' · '+e(t)).join('')}</small></span>${icon('external')}</a>`).join('')}</section>`;}

function linksPanel(l){if(!l||!l.total)return '';const t=l.totals||{};return `<section class="panel system-panel"><div class="panel-heading"><div><h2>${icon('check')}Enlaces verificados</h2><p class="panel-subtitle">Cada enlace que muestra la plataforma se revisa en cada ejecución · ${e(dateLabel(l.checked_at))}</p></div></div><div class="link-totals"><span><b>${e(l.total)}</b> enlaces</span><span class="status-ok"><b>${e(t.ok||0)}</b> responden</span><span><b>${e(t.bloqueado||0)}</b> bloquean al verificador</span><span class="status-fail"><b>${e(t.roto||0)}</b> rotos</span><span><b>${e(t['sin respuesta']||0)}</b> sin respuesta</span></div>${l.problems?.length?`<table class="case-table"><thead><tr><th>Enlace</th><th>Estado</th><th>Código</th></tr></thead><tbody>${l.problems.map(x=>`<tr><td><a href="${e(safeURL(x.url))}" target="_blank" rel="noopener">${e(x.url.slice(0,90))}</a></td><td>${e(x.state)}</td><td>${e(x.code||'—')}</td></tr>`).join('')}</tbody></table>`:''}<div class="panel-footer"><span>«Bloquea al verificador» (401/403/429) no significa que el documento falte: varios servidores del Estado rechazan las IP de GitHub.</span></div></section>`;}
function systemView(){const s=state.payload.system||{};const runs=s.runs||[];const last=runs[0];return `<section class="panel system-panel"><div class="panel-heading"><div><h2>${icon('activity')}Ejecuciones automáticas</h2><p class="panel-subtitle">GitHub Actions corre el ciclo completo cada día a las 7:00 a. m. (Lima) y vuelve a publicar este sitio</p></div><a class="text-link" href="${e(safeURL(s.actions))}" target="_blank" rel="noopener">Ver en GitHub Actions ${icon('external')}</a></div><div class="system-badges"><img alt="Estado del workflow diario" src="https://github.com/AlexNoblejas/pulso-territorial/actions/workflows/pages.yml/badge.svg"><img alt="Estado de las pruebas" src="https://github.com/AlexNoblejas/pulso-territorial/actions/workflows/ci.yml/badge.svg"></div>${last?`<div class="run-card"><strong>Última ejecución: ${e(dateLabel(last.finished_at))} · ${e(new Date(last.finished_at).toLocaleTimeString('es-PE',{hour:'2-digit',minute:'2-digit'}))} · ${last.ok?'todo correcto':'con pasos fallidos'} · origen: ${e(last.trigger)}</strong>${last.run_url?` <a class="text-link" href="${e(safeURL(last.run_url))}" target="_blank" rel="noopener">registro de la ejecución ${icon('external')}</a>`:''}<table class="case-table"><thead><tr><th>Paso</th><th>Resultado</th><th>Detalle</th><th>Tiempo</th></tr></thead><tbody>${last.steps.map(st=>`<tr><td>${e(st.label)}</td><td>${st.ok?'<span class="status-ok">OK</span>':'<span class="status-fail">Error</span>'}</td><td>${e(st.detail)}</td><td>${e(st.seconds)} s</td></tr>`).join('')}</tbody></table></div>`:empty('Sin ejecuciones registradas','Ejecuta python -m pulso.pipeline o espera el ciclo diario.')}</section><section class="panel system-panel"><div class="panel-heading"><div><h2>${icon('sources')}Conectores</h2><p class="panel-subtitle">Última lectura de cada fuente · si una falla se conserva su última copia y se informa aquí</p></div></div><table class="case-table"><thead><tr><th>Fuente</th><th>Estado</th><th>Registros</th><th>Última lectura</th></tr></thead><tbody>${(s.connectors||[]).map(c=>`<tr><td>${e(c.label)}${c.error?`<div class="case-place">${e(c.error)}</div>`:''}</td><td>${c.ok?'<span class="status-ok">Responde</span>':'<span class="status-fail">Falló</span>'}</td><td>${e(c.items)}${c.new?` <small>(${e(c.new)} nuevos)</small>`:''}</td><td>${e(c.checked_at?dateLabel(c.checked_at)+' '+new Date(c.checked_at).toLocaleTimeString('es-PE',{hour:'2-digit',minute:'2-digit'}):'—')}</td></tr>`).join('')}</tbody></table></section>${linksPanel(s.links)}${runs.length>1?`<section class="panel system-panel"><div class="panel-heading"><div><h2>${icon('clock')}Historial</h2><p class="panel-subtitle">Últimas ${runs.length} ejecuciones</p></div></div><table class="case-table"><thead><tr><th>Fecha</th><th>Origen</th><th>Pasos OK</th></tr></thead><tbody>${runs.map(r=>`<tr><td>${e(dateLabel(r.finished_at))} ${e(new Date(r.finished_at).toLocaleTimeString('es-PE',{hour:'2-digit',minute:'2-digit'}))}</td><td>${e(r.trigger)}</td><td>${r.steps.filter(x=>x.ok).length}/${r.steps.length}</td></tr>`).join('')}</tbody></table></section>`:''}`;}

function geoperuLayers(){const gp=(state.geo||{}).geoperu?.layers||{};return Object.entries(gp).filter(([,l])=>l.count).map(([key,l])=>({key:'gp_'+key,label:l.label,color:l.color,data:l.data,count:l.count}));}

document.addEventListener('click',event=>{const dot=event.target.closest?.('[data-lane-month]');if(dot){document.querySelectorAll('.lane-dot.selected').forEach(d=>d.classList.remove('selected'));document.querySelectorAll(`[data-lane-month="${dot.dataset.laneMonth}"]`).forEach(d=>d.classList.add('selected'));laneMonthDetail(dot.dataset.laneMonth);return;}const alertCase=event.target.closest?.('[data-open-alert-case]');if(alertCase){location.hash='#conflictos';setTimeout(()=>openCase(alertCase.dataset.openAlertCase),60);}});
document.addEventListener('keydown',event=>{if((event.key==='Enter'||event.key===' ')&&event.target.dataset?.laneMonth){event.preventDefault();event.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
const ORGS={antamina:'Compañía Minera Antamina',mineria:'Minera Las Bambas',hidrocarburos:'Petroperú'};
// Demo access, not security: a static site cannot protect data with a password checked in the browser.
const DEMO_PASSWORD='2026';
function readSession(){try{const s=JSON.parse(sessionStorage.getItem('pulso-session')||'null');return s&&ORGS[s.org]&&s.user?s:null;}catch{return null;}}
function login(event){event.preventDefault();const user=$('#login-user').value.trim(),org=$('#login-org').value,pass=$('#login-pass').value;if(user.length<2||pass!==DEMO_PASSWORD||!ORGS[org]){$('#login-error').hidden=false;$('#login-pass').value='';return;}const session={user,org,since:new Date().toISOString()};try{sessionStorage.setItem('pulso-session',JSON.stringify(session));}catch{}$('#login-error').hidden=true;$('#login-screen').hidden=true;startSession(session);}
function logout(){try{sessionStorage.removeItem('pulso-session');}catch{}location.href=location.pathname;}
function startSession(session){state.session=session;state.company=session.org;state.period='';state.selectedCase=null;const initials=session.user.split(/\s+/).map(w=>w[0]).join('').slice(0,2).toUpperCase();$('.analyst-avatar').textContent=initials;$('.analyst-avatar').title=`${session.user} · ${ORGS[session.org]}`;$('#session-title').textContent=session.user;$('#session-detail').textContent=`Analista de gestión social · ${ORGS[session.org]}. Sesión iniciada ${new Date(session.since).toLocaleString('es-PE')}.`;navigate();loadPortfolio();initLore();if(!sessionStorage.getItem('pulso-lore-greeted')){try{sessionStorage.setItem('pulso-lore-greeted','1');}catch{}setTimeout(()=>toggleLore(true),1600);}}
// ===== Imágenes satelitales, focos históricos, lectura del mapa y actores =====
// Sentinel-2 cloudless 2023 (EOX, CC BY-NC-SA 4.0): imágenes reales sin nubes; uso académico.
const SATELLITE={tiles:['https://tiles.maps.eox.at/wmts/1.0.0/s2cloudless-2023_3857/default/g/{z}/{y}/{x}.jpg'],tileSize:256,maxzoom:15,attribution:'Sentinel-2 cloudless 2023 · <a href="https://s2maps.eu" target="_blank" rel="noopener">EOX IT Services</a> (datos Copernicus Sentinel modificados)'};
function addSatellite(map){try{map.addSource('pulso-satellite-src',{type:'raster',...SATELLITE});map.addLayer({id:'pulso-satellite',type:'raster',source:'pulso-satellite-src',layout:{visibility:state.basemap==='satelite'?'visible':'none'},paint:{'raster-saturation':-.05,'raster-contrast':.05}},map.getStyle().layers.find(l=>l.type==='symbol')?.id);}catch{}}
function basemapToggle(){return `<div class="segmented" aria-label="Fondo del mapa"><button data-basemap="mapa" class="${state.basemap!=='satelite'?'active':''}">Mapa</button><button data-basemap="satelite" class="${state.basemap==='satelite'?'active':''}">Satélite</button></div>`;}
function addHistoryLayer(map,entry,geo){const data=geo.history_points;if(!data?.features?.length)return;try{map.addSource('pulso-history',{type:'geojson',data});map.addLayer({id:'pulso-history',type:'circle',source:'pulso-history',paint:{'circle-radius':['interpolate',['linear'],['get','conflicts'],1,8,10,26],'circle-color':'#d0503c','circle-opacity':.32,'circle-stroke-color':'#a5483c','circle-stroke-width':1.5}});entry.layers.history=['pulso-history'];const checked=$('[data-layer="history"]')?.checked;map.setLayoutProperty('pulso-history','visibility',checked===false?'none':'visible');map.on('click','pulso-history',ev=>{const p=ev.features[0].properties;new window.maplibregl.Popup().setLngLat(ev.lngLat).setHTML(`<strong>${e(p.district)} · ${e(p.conflicts)} conflictos 2012-2025</strong>${e(p.names)}<small>Punto distrital de referencia · base de reportes de la Defensoría</small>`).addTo(map);});}catch{}}
function mapReadingPanel(){const notes=state.payload.map_reading||[];if(!notes.length)return '';return `<section class="panel map-reading"><div class="panel-heading"><div><h2>${icon('sparkles')}Lo que dice el mapa</h2><p class="panel-subtitle">Hallazgos calculados con las capas de GEOPERÚ y el historial · sin afirmar causas</p></div></div><div class="reading-grid">${notes.map(n=>`<article><h3>${e(n.title)}</h3><p>${e(n.text)}</p><small>${e(n.source)}</small></article>`).join('')}</div>${figCaption('Cruces espaciales entre las capas oficiales (concesiones, comunidades, pasivos, oleoducto) y la ubicación distrital de los conflictos 2012-2025.','GEOPERÚ (MINAM) por ArcGIS REST; base de reportes de la Defensoría; cálculo con shapely.',`Capas: ${dateLabel(((state.geo||{}).geoperu||{}).fetched_at)}.`)}</section>`;}
function stakeholdersPanel(){const s=state.payload.stakeholders;if(!s?.actors?.length)return '';const tab=state.actorTab||'Sociedad';const list=s.actors.filter(a=>a.type===tab).slice(0,15);const max=Math.max(1,...list.map(a=>a.conflicts));return `<section class="panel"><div class="panel-heading"><div><h2>${icon('dialogue')}Mapa de actores recurrentes</h2><p class="panel-subtitle">Quién aparece una y otra vez en los ${e(s.conflicts)} conflictos de ${e(state.payload.company.name)} (2012-2025)</p></div><div class="segmented">${['Sociedad','Estado','Empresa'].map(t=>`<button data-actor-tab="${t}" class="${tab===t?'active':''}">${t==='Sociedad'?'Comunidades y organizaciones':t}</button>`).join('')}</div></div><div class="actor-bars">${list.map(a=>`<div class="actor-bar"><div><strong>${e(a.name)}</strong><small>${e(a.role)} · ${e(a.months)} meses · último registro ${e(a.last)}</small></div><span><em style="width:${a.conflicts/max*100}%"></em><b>${e(a.conflicts)}</b></span></div>`).join('')||'<p class="report-note">Sin actores de este tipo.</p>'}</div>${figCaption('Actores nombrados en los conflictos de la empresa, por número de conflictos distintos en los que aparecen. Ayuda a decidir con quién sostener una relación permanente, no solo caso por caso.','Base de actores de la tesis (24,100 registros limpios de los reportes de la Defensoría 2012-2025).','Hasta diciembre de 2025.')}</section>`;}
function officialChart(){const o=state.national?.official_series?.series;if(!o?.length)return '';const rows=o.filter(r=>r.total);const max=Math.max(...rows.map(r=>r.total));const W=900,H=190,x=i=>40+i*(W-60)/(rows.length-1),y=v=>H-26-(v/max)*(H-48);const line=(k,c,w)=>`<path d="${rows.map((r,i)=>r[k]==null?'':`${i&&rows[i-1][k]!=null?'L':'M'}${x(i).toFixed(1)},${y(r[k]).toFixed(1)}`).join('')}" fill="none" stroke="${c}" stroke-width="${w}"/>`;const peak=rows.reduce((a,b)=>b.total>a.total?b:a);const lastR=rows[rows.length-1];return `<section class="panel"><div class="panel-heading"><div><h2>${icon('activity')}Veintidós años de conflictividad oficial (2004-2025)</h2><p class="panel-subtitle">Total publicado por la Defensoría cada mes · pico: ${e(peak.total)} en ${e(periodLabel(peak.period))} · último: ${e(lastR.total)} en ${e(periodLabel(lastR.period))}</p></div></div><div class="evolution-body"><svg viewBox="0 0 ${W} ${H}" class="national-chart" role="img" aria-label="Serie oficial de conflictos">${[0,.5,1].map(t=>`<line x1="40" x2="${W-20}" y1="${y(max*t)}" y2="${y(max*t)}" stroke="#eef2ec"/><text x="34" y="${y(max*t)+3}" font-size="9" text-anchor="end" fill="#9aaa9a">${Math.round(max*t)}</text>`).join('')}${line('total','#16343e',2)}${line('activos','#167b70',1.4)}${line('latentes','#d0a24a',1.4)}${line('socioambientales','#c0794f',1.4)}${rows.map((r,i)=>r.period.endsWith('-01')&&+r.period.slice(0,4)%3===1?`<text x="${x(i)}" y="${H-8}" font-size="9" text-anchor="middle" fill="#9aaa9a">${r.period.slice(0,4)}</text>`:'').join('')}</svg><div class="chart-legend"><span><i style="background:#16343e"></i>Total publicado</span><span><i style="background:#167b70"></i>Activos</span><span><i style="background:#d0a24a"></i>Latentes</span><span><i style="background:#c0794f"></i>Socioambientales</span></div></div>${figCaption('Conflictos sociales registrados cada mes en el Perú según la cifra que publica la Defensoría en su reporte.','Base histórica del autor (hoja SERIE_MENSUAL), transcrita de 258 reportes con su página de PDF.','Mayo 2004 a diciembre 2025; meses sin reporte quedan sin dato.')}</section>`;}
document.addEventListener('click',ev=>{const b=ev.target.closest?.('[data-basemap]');if(b){state.basemap=b.dataset.basemap;document.querySelectorAll('[data-basemap]').forEach(x=>x.classList.toggle('active',x.dataset.basemap===state.basemap));for(const {map} of state.maps){try{map.setLayoutProperty('pulso-satellite','visibility',state.basemap==='satelite'?'visible':'none');}catch{}}return;}const t=ev.target.closest?.('[data-actor-tab]');if(t){state.actorTab=t.dataset.actorTab;render();}});
// ===== Conflictos del país =====
const TYPE_COLORS={'Socioambiental':'#167b70','Asuntos de gobierno local':'#2563b9','Asuntos de gobierno nacional':'#5b6fa8','Asuntos de gobierno regional':'#8a6d9e','Demarcación territorial':'#b58438','Laboral':'#c0794f','Comunal':'#6f9d6a','Otros asuntos':'#9aa5a0'};
const typeColor=t=>TYPE_COLORS[t]||'#9aa5a0';
async function loadNational(){if(state.national||state.nationalLoading)return;state.nationalLoading=true;try{const r=await fetch(apiURL('national'),{headers:{Accept:'application/json'}});state.national=r.ok?await r.json():{cases:[]};}catch{state.national={cases:[]};}state.nationalLoading=false;if(state.view==='pais')render();}
function nationalFilter(){const f=state.nf||(state.nf={q:'',region:'',type:'',scope:'all'});const q=normalize(f.q);return (state.national?.cases||[]).filter(c=>(!f.region||c.region===f.region)&&(!f.type||c.type===f.type)&&(f.scope==='all'||(f.scope==='territory'&&(c.territory||[]).includes(state.company))||(f.scope==='company'&&(c.companies||[]).includes(state.company))||(f.scope==='dialogue'&&c.dialogue))&&(!q||normalize([c.name,c.location,c.description,c.actors?.primarios].join(' ')).includes(q)));}
function nationalDetail(c){const a=c.actors||{};return `<tr class="ncase-detail"><td colspan="6"><div class="ndetail"><p><b>Caso.</b> ${e(c.description)}</p>${c.narrative?`<p><b>Hechos del mes.</b> ${e(c.narrative.slice(0,900))}${c.narrative.length>900?'…':''}</p>`:''}<dl class="actor-list">${[['primarios','Partes'],['secundarios','Intervienen'],['terciarios','Median o supervisan']].map(([k,l])=>a[k]?`<div><dt>${l}</dt><dd>${a[k].split(/,\s*(?![^()]*\))/).map(x=>`<span class="actor-chip">${e(x.trim().replace(/\.$/,''))}</span>`).join('')}</dd></div>`:'').join('')}</dl><p class="report-note">${e(c.location)} · ingreso al registro: ${e(c.registered||'s/d')} · competencia: ${e(c.competence||'s/d')} · ubicación en el mapa: ${e(c.coordinate_precision)} · <a class="timeline-source" href="${e(safeURL(c.source_url))}" target="_blank" rel="noopener">ficha oficial de la Defensoría ${icon('external')}</a></p></div></td></tr>`;}
function historyChart(){const h=state.national?.history;if(!h?.series?.length)return '';const deps=(TERRITORY_DEPS[state.company]||[]);const depSeries=Object.entries(h.departments||{}).filter(([k])=>deps.includes(normalize(k))).map(([k,v])=>[k,Object.fromEntries(v.map(x=>[x.period,x.total]))]);const rows=h.series;const max=Math.max(...rows.map(r=>r.total));const W=900,H=180,x=i=>40+i*(W-60)/(rows.length-1),y=v=>H-26-(v/max)*(H-50);const line=(get,color,width)=>`<path d="${rows.map((r,i)=>{const v=get(r);return v==null?'':`${i&&get(rows[i-1])!=null?'L':'M'}${x(i).toFixed(1)},${y(v).toFixed(1)}`;}).join('')}" fill="none" stroke="${color}" stroke-width="${width}"/>`;const depColors=['#c0794f','#8a6d9e','#2563b9'];const years=rows.map((r,i)=>[r.period,i]).filter(([p])=>p.endsWith('-01')&&+p.slice(0,4)%2===0);const depTotals=deps.length?(h.cases||[]).filter(c=>deps.includes(normalize(c.department))):[];return `<section class="panel"><div class="panel-heading"><div><h2>${icon('clock')}Quince años de conflictividad (2012-2025)</h2><p class="panel-subtitle">Conflictos registrados por mes en el país${depSeries.length?' y en tus departamentos':''}</p></div></div><div class="evolution-body"><svg viewBox="0 0 ${W} ${H}" class="national-chart" role="img" aria-label="Conflictos registrados por mes">${[0,.5,1].map(t=>`<line x1="40" x2="${W-20}" y1="${y(max*t)}" y2="${y(max*t)}" stroke="#eef2ec"/><text x="34" y="${y(max*t)+3}" font-size="9" text-anchor="end" fill="#9aaa9a">${Math.round(max*t)}</text>`).join('')}${line(r=>r.total,'#16343e',2)}${line(r=>r.activo,'#167b70',1.4)}${line(r=>r.latente,'#d0a24a',1.4)}${depSeries.map(([k,m],j)=>line(r=>m[r.period]??0,depColors[j],1.8)).join('')}${years.map(([p,i])=>`<text x="${x(i)}" y="${H-8}" font-size="9" text-anchor="middle" fill="#9aaa9a">${p.slice(0,4)}</text>`).join('')}</svg><div class="chart-legend"><span><i style="background:#16343e"></i>Total país</span><span><i style="background:#167b70"></i>Activos</span><span><i style="background:#d0a24a"></i>Latentes</span>${depSeries.map(([k],j)=>`<span><i style="background:${depColors[j]}"></i>${e(k)}</span>`).join('')}</div>${deps.length?`<p class="report-note">En tus departamentos (${e(depSeries.map(([k])=>k).join(' y ')||deps.join(', '))}) se registraron ${depTotals.length} conflictos distintos entre 2012 y 2025; ${depTotals.filter(c=>/antamina|bambas|petroper/i.test(c.companies||'')).length} nombran a una empresa de las carteras.</p>`:''}</div>${figCaption('Línea oscura: conflictos registrados cada mes en todo el Perú; verde y ocre: activos y latentes; colores adicionales: tus departamentos.','Base de tesis con los reportes mensuales de la Defensoría (33,845 filas, 1,073 conflictos).','Enero 2012 a diciembre 2025.')}</section>`;}
const TERRITORY_DEPS={antamina:['ancash','huanuco'],mineria:['apurimac','cusco'],hidrocarburos:['loreto','amazonas','piura']};
function nationalView(){if(!state.national){loadNational();return '<div class="loading-state"><div class="loader"></div>Reuniendo los conflictos del país…</div>';}const all=state.national.cases||[];const f=state.nf||(state.nf={q:'',region:'',type:'',scope:'all'});const rows=nationalFilter();const mine=all.filter(c=>(c.companies||[]).includes(state.company)).length,terr=all.filter(c=>(c.territory||[]).includes(state.company)).length;const types=Object.entries(all.reduce((m,c)=>(m[c.type]=(m[c.type]||0)+1,m),{})).sort((a,b)=>b[1]-a[1]);const regions=[...new Set(all.map(c=>c.region))].sort();return `<section class="kpi-grid">${metric('Conflictos activos con ficha',all.length,`Reporte de la Defensoría · ${periodLabel(state.national.period)}`,'layers',true)}${metric('En tus departamentos',terr,(TERRITORY_DEPS[state.company]||[]).join(' · ')||'—','map')}${metric(`Nombran a ${state.payload.company.name}`,mine,'Como actor en la ficha oficial','target')}${metric('Con diálogo',all.filter(c=>c.dialogue).length,'Según la ficha','dialogue')}</section><section class="national-grid"><section class="panel"><div class="panel-heading"><div><h2>${icon('map')}Mapa de los conflictos del país</h2><p class="panel-subtitle">Color por tipo · borde oscuro: nombran a tu empresa · haz clic en un punto</p></div>${basemapToggle()}</div><div class="map-wrap"><div id="national-map" class="territory-map big-map"></div></div>${figCaption('Cada punto es un conflicto activo del reporte vigente, ubicado en su distrito, provincia o departamento según lo que informa la ficha.','Defensoría del Pueblo (fichas); límites distritales de GEOPERÚ para ubicar.',`Reporte de ${periodLabel(state.national.period)}. ${all.filter(c=>!c.coordinates).length} casos multirregionales o nacionales no tienen punto.`)}</section><section class="panel type-panel"><div class="panel-heading"><div><h2>${icon('layers')}Por tipo</h2><p class="panel-subtitle">Haz clic para filtrar</p></div></div><div class="type-bars">${types.map(([t,n])=>`<button class="type-bar ${f.type===t?'active':''}" data-ntype="${e(t)}"><span><i style="background:${typeColor(t)}"></i>${e(t)}</span><b>${n}</b><em style="width:${n/types[0][1]*100}%;background:${typeColor(t)}"></em></button>`).join('')}</div></section></section><section class="panel"><div class="filter-row"><label class="search-field">${icon('search')}<input id="nsearch" value="${e(f.q)}" placeholder="Busca por nombre, lugar o actor"></label><select id="nregion"><option value="">Todas las regiones</option>${regions.map(r=>`<option ${f.region===r?'selected':''}>${e(r)}</option>`).join('')}</select><select id="nscope">${[['all','Todo el país'],['territory','Mis departamentos'],['company','Nombran a mi empresa'],['dialogue','Con diálogo']].map(([v,l])=>`<option value="${v}" ${f.scope===v?'selected':''}>${l}</option>`).join('')}</select>${f.type?`<button class="button button-quiet" data-ntype="">Quitar tipo: ${e(f.type)}</button>`:''}<span class="filter-count">${rows.length} de ${all.length}</span></div><div class="table-wrapper"><table class="case-table"><thead><tr><th>Conflicto</th><th>Región</th><th>Tipo</th><th>Fase</th><th>Diálogo</th><th>Ingreso</th></tr></thead><tbody>${rows.map(c=>`<tr data-ncase="${e(c.code)}" class="${state.nsel===c.code?'selected':''}"><td><div class="case-name">${e(c.name)}${(c.companies||[]).includes(state.company)?' <span class="media-tag case">Tu empresa</span>':''}</div><div class="case-place">${e(c.location.slice(0,90))}</div></td><td>${e(c.region)}</td><td><span class="type-dot" style="background:${typeColor(c.type)}"></span>${e(c.type)}</td><td>${e(c.phase)}</td><td>${c.dialogue?'Sí':'No'}</td><td>${e(c.registered)}</td></tr>${state.nsel===c.code?nationalDetail(c):''}`).join('')}</tbody></table></div>${rows.length?'':empty('Sin conflictos con ese filtro','Prueba otra región o quita el filtro de tipo.')}</section>${officialChart()}${historyChart()}`+note('La vista nacional muestra todos los conflictos activos con ficha en el reporte vigente. Estar en tu departamento no significa que el conflicto involucre a tu empresa.');}
function initNationalMap(){const container=$('#national-map');if(!container||!window.maplibregl)return;const pts=(state.national?.cases||[]).filter(c=>validCoordinates(c.coordinates));const map=new window.maplibregl.Map({container,style:(state.geo||{}).map_style_url||'https://tiles.openfreemap.org/styles/positron',center:[-75.2,-9.4],zoom:4.35,attributionControl:true});state.maps.push({map,markers:[],layers:{}});map.addControl(new window.maplibregl.NavigationControl({showCompass:false}),'top-right');map.on('load',()=>{addSatellite(map);map.addSource('national',{type:'geojson',data:{type:'FeatureCollection',features:pts.map(c=>({type:'Feature',geometry:{type:'Point',coordinates:c.coordinates},properties:{code:c.code,name:c.name,type:c.type,phase:c.phase,precision:c.coordinate_precision,mine:(c.companies||[]).includes(state.company)?1:0,color:typeColor(c.type)}}))}});map.addLayer({id:'national-points',type:'circle',source:'national',paint:{'circle-radius':['case',['==',['get','mine'],1],9,6],'circle-color':['get','color'],'circle-opacity':.85,'circle-stroke-color':['case',['==',['get','mine'],1],'#16343e','#ffffff'],'circle-stroke-width':['case',['==',['get','mine'],1],3,1.5]}});map.on('click','national-points',ev=>{const p=ev.features[0].properties;new window.maplibregl.Popup({closeButton:true}).setLngLat(ev.lngLat).setHTML(`<strong>${e(p.name)}</strong>${e(p.type)} · ${e(p.phase)}<small>${e(p.precision)}</small><button class="text-link" data-ncase="${e(p.code)}">Ver ficha</button>`).addTo(map);});map.on('mouseenter','national-points',()=>{map.getCanvas().style.cursor='pointer';});map.on('mouseleave','national-points',()=>{map.getCanvas().style.cursor='';});});}
document.addEventListener('click',ev=>{const n=ev.target.closest?.('[data-ncase]');if(n){state.nsel=state.nsel===n.dataset.ncase?null:n.dataset.ncase;if(state.view!=='pais'){location.hash='#pais';return;}render();setTimeout(()=>document.querySelector(`tr[data-ncase="${state.nsel}"]`)?.scrollIntoView({block:'center',behavior:'smooth'}),80);return;}const t=ev.target.closest?.('[data-ntype]');if(t){state.nf.type=state.nf.type===t.dataset.ntype?'':t.dataset.ntype;render();}});
document.addEventListener('change',ev=>{if(ev.target.id==='nregion'){state.nf.region=ev.target.value;render();}if(ev.target.id==='nscope'){state.nf.scope=ev.target.value;render();}});
document.addEventListener('input',ev=>{if(ev.target.id==='nsearch'){state.nf.q=ev.target.value;clearTimeout(state.nTimer);state.nTimer=setTimeout(()=>{const pos=ev.target.selectionStart;render();const i=$('#nsearch');if(i){i.focus();i.setSelectionRange(pos,pos);}},280);}});

// ===== Lore, la llamita asistente =====
const LORE_SVG=`<svg viewBox="0 0 64 64" aria-hidden="true"><path d="M20 10c-2-6 3-8 5-3l2 6M44 10c2-6-3-8-5-3l-2 6" fill="#f3e6cf" stroke="#7a5b3a" stroke-width="1.6" stroke-linecap="round"/><path d="M19 12c3-6 23-6 26 0l-1 4H20z" fill="#d6455f"/><path d="M19 15h26" stroke="#f2b632" stroke-width="2.4"/><path d="M22 13l2-3 2 3 2-3 2 3 2-3 2 3 2-3 2 3 2-3 2 3" fill="none" stroke="#2f8f7a" stroke-width="1.2"/><circle cx="32" cy="7" r="2.6" fill="#f2b632"/><ellipse cx="32" cy="33" rx="15" ry="16" fill="#fbf3e4" stroke="#7a5b3a" stroke-width="1.6"/><path d="M19 22c4 3 22 3 26 0" fill="#f3e6cf"/><ellipse cx="25.5" cy="30" rx="2.6" ry="3.2" fill="#2b2420"/><ellipse cx="38.5" cy="30" rx="2.6" ry="3.2" fill="#2b2420"/><circle cx="26.4" cy="28.8" r=".9" fill="#fff"/><circle cx="39.4" cy="28.8" r=".9" fill="#fff"/><ellipse cx="22" cy="36" rx="3" ry="1.8" fill="#f4a9b4" opacity=".8"/><ellipse cx="42" cy="36" rx="3" ry="1.8" fill="#f4a9b4" opacity=".8"/><ellipse cx="32" cy="40" rx="6.5" ry="5" fill="#f3e6cf"/><path d="M30 39.5c1 1 3 1 4 0M32 40.5v1.6" stroke="#7a5b3a" stroke-width="1.3" fill="none" stroke-linecap="round"/><path d="M22 47c3 5 17 5 20 0" fill="#fbf3e4"/><path d="M20 49c4 3 20 3 24 0" stroke="#d6455f" stroke-width="2.6" fill="none"/></svg>`;
const GLOSSARY=[
 [/latente/,'Conflicto <b>latente</b>: no se expresa públicamente, pero las causas siguen presentes y puede activarse en cualquier momento.'],
 [/\bactivo/,'Conflicto <b>activo</b>: alguna de las partes lo expresa públicamente con demandas, movilizaciones u otras acciones. Así lo registra la Defensoría.'],
 [/resuelto|retirado|fusionado/,'<b>Resuelto</b>: las partes llegaron a una solución. <b>Retirado</b>: la Defensoría lo saca de su registro activo. <b>Fusionado</b>: se integró a otro caso. El motivo exacto está en el reporte del mes.'],
 [/temprana|escalamiento|crisis|desescal|fase/,'Las <b>fases</b> describen el momento del conflicto: <b>temprana</b> (aparecen las demandas), <b>escalamiento</b> (sube la tensión y las medidas de fuerza), <b>crisis</b> (confrontación o violencia), <b>desescalamiento</b> (baja la tensión, suele abrirse diálogo) y <b>acuerdos</b> (se negocian o implementan compromisos). La fase la asigna la Defensoría; no es una predicción.'],
 [/primario|secundario|terciario|actor/,'Actores: los <b>primarios</b> son las partes del conflicto; los <b>secundarios</b> apoyan o intervienen sin ser parte directa; los <b>terciarios</b> no tienen un interés directo y suelen mediar o supervisar (por ejemplo, la PCM o la propia Defensoría). Los ves en cada caso, en "Con quién gestionar".'],
 [/dialogo|mesa/,'<b>Diálogo</b>: la ficha indica si existe un espacio de diálogo entre las partes. Que haya diálogo no significa que los acuerdos se cumplan; por eso PulsoTerritorial sigue los compromisos y sus plazos.'],
 [/pasivo/,'<b>Pasivo ambiental</b>: instalación, residuo o daño de una actividad minera o de hidrocarburos ya abandonada que sigue siendo un riesgo. El inventario 2022 viene de GEOPERÚ.'],
 [/cuenca|hidrograf/,'<b>Unidad hidrográfica</b>: el área que drena hacia un mismo río o quebrada. Ayuda a ver qué comunidades comparten agua con la operación.'],
 [/concesion/,'<b>Concesión</b>: derecho otorgado por el Estado para explorar o explotar un área. En el mapa ves las concesiones cuyo titular es tu empresa, según GEOPERÚ.'],
 [/brecha/,'<b>Brecha de información</b>: la prensa habla de un caso y ninguna fuente oficial lo actualiza hace más de 45 días. Conviene confirmar con la Defensoría o la PCM.'],
 [/geoperu/,'<b>GEOPERÚ</b> es el visor de información territorial del Estado. PulsoTerritorial consulta su geoservidor (MINAM) por ArcGIS REST: concesiones, comunidades, cuencas, áreas protegidas y pasivos.'],
 [/willaqniki|sgsd/,'<b>Willaqniki</b> es la revista de la Secretaría de Gestión Social y Diálogo de la PCM; reporta mesas, acuerdos y su seguimiento.'],
 [/ogasa|sinia/,'<b>OGASA</b> es la oficina de asuntos socioambientales del MINAM; publica cada mes en SINIA un informe de conflictos socioambientales que priorizó.'],
];
const VIEW_HELP={resumen:'Estás en el <b>Resumen</b>: arriba las alertas, luego tus KPIs, el mapa de tu cartera, las lecturas del período, el pulso de prensa y la evolución histórica.',alertas:'Estás en <b>Alertas</b>: lo que conviene gestionar hoy. Cada tarjeta dice la regla que la activó y enlaza su evidencia. Abajo están todas las reglas.',territorio:'Estás en <b>Territorio</b>: el mapa 3D de tu operación. En el panel izquierdo activa las capas de GEOPERÚ (concesiones, comunidades, cuencas, áreas protegidas, pasivos).',conflictos:'Estás en <b>Conflictos</b>: haz clic en un caso para ver con quién gestionar, la línea de tiempo por actor (clic en un punto para ver ese mes) y el contexto territorial. Abajo está el historial 2012-2025.',pais:'Estás en <b>Conflictos del país</b>: los conflictos activos de todo el Perú. Filtra por región, por tipo o por "mis departamentos"; clic en una fila o en un punto del mapa para ver su ficha.',fuentes:'Estás en <b>Fuentes</b>: qué instituciones sustentan el monitoreo, cómo mira cada una y la actuación del Estado en el territorio.',reportes:'Estás en <b>Reportes</b>: genera el reporte mensual narrativo con tu nombre y guárdalo como PDF desde el navegador.',sistema:'Estás en <b>Estado del sistema</b>: la bitácora de cada ejecución automática, el estado de cada fuente y la verificación de enlaces.'};
const loreLink=(href,label)=>`<a href="${e(href)}" ${href.startsWith('#')?'':'target="_blank" rel="noopener"'}>${e(label)}</a>`;
const LORE_STOP=new Set(['conflicto','conflictos','caso','casos','sobre','cuantos','cuantas','donde','quien','quienes','tiene','tengo','esta','estan','este','empresa','cual','cuales','como','dime','sabes','informacion','pasa','paso','sucede','dice','dicen','hubo','hace','tema','quiero','saber','puedes','ahora','hoy','gano','mundial','para','porque','todo','todos','algo','favor']);
function loreFind(q,items,name,rest=()=>''){const words=normalize(q).split(/[^a-z0-9ñ]+/).filter(w=>w.length>3&&!LORE_STOP.has(w));if(!words.length)return [];const hit=(text,w)=>new RegExp('\\b'+w).test(text);return items.map(it=>{const n=normalize(name(it)),r=normalize(rest(it));return [it,words.reduce((s,w)=>s+(hit(n,w)?3:hit(r,w)?1:0),0)];}).filter(([,sc])=>sc>=3).sort((a,b)=>b[1]-a[1]).map(([it])=>it);}
async function loreAnswer(question){const q=normalize(question);const p=state.payload;if(!p)return 'Todavía estoy cargando tu cartera. Prueba en un segundo.';
 const context=loreContext();
 const command=explicitLoreNavigation(question,context);
 if(command?.action){const done=runLoreAction(command.action);return done?`Listo. Abrí ${e(command.label||command.action.view||'el expediente')} en la plataforma.`:'No pude abrir esa selección en esta cartera.';}
 if(command?.choices)return `Hay varios expedientes posibles. Elige cuál quieres abrir:${loreActionMarkup(command.choices,context)}`;
 const cited=loreEvidenceAnswer(question,context);if(cited)return cited;
 if(/\b20(?:1[2-9]|2[0-5])\b/.test(q)){if(!state.national)await loadNational();return loreYearAnswer(question,loreContext());}
 if(/cuant|cantidad|numero/.test(q)&&/latente|activo|resuelto/.test(q)){if(!state.national)await loadNational();return loreStatusAnswer(question,loreContext());}

 if(/^(hola|buenas|hey|holi)|quien eres|que eres|como te llamas/.test(q))return `¡Hola${state.session?', '+e(state.session.user.split(' ')[0]):''}! Soy <b>Lore</b>, una llamita que conoce los datos de PulsoTerritorial. Puedo decirte qué alertas tienes, con quién gestionar un conflicto, cuántos conflictos hay en una región, qué significa un término o cómo usar cada pantalla. Respondo solo con lo que hay en la plataforma y te digo de dónde sale.`;
 if(/empez|tour|como (uso|funciona|se usa)|ayuda|que hago|guia/.test(q))return `Te propongo este recorrido:<br>1. ${loreLink('#alertas','Alertas')}: qué gestionar hoy.<br>2. ${loreLink('#conflictos','Conflictos')}: abre un caso y revisa "Con quién gestionar" y su línea de tiempo.<br>3. ${loreLink('#pais','Conflictos del país')}: todo el Perú y tus departamentos.<br>4. ${loreLink('#territorio','Territorio')}: activa las capas de GEOPERÚ.<br>5. ${loreLink('#reportes','Reportes')}: descarga tu reporte mensual.<br>Y si dudas de los datos: ${loreLink('#sistema','Estado del sistema')}.`;
 if(/esta pantalla|que veo|donde estoy|esta vista|esta seccion/.test(q))return VIEW_HELP[state.view]||VIEW_HELP.resumen;
 if(/actualiz|automat|de donde|fuente|dato|confiable|verific/.test(q)&&!/prensa|noticia/.test(q)){const run=p.system?.runs?.[0];return `Cada mañana a las 7:00, GitHub Actions descarga solo: el reporte de la Defensoría, notas de gob.pe (PCM, MINEM, MINAM, OEFA, ANA, PNP), informes del MINAM y la PCM en PDF, prensa por RSS y capas de GEOPERÚ. Luego verifica cada enlace.${run?` Última ejecución: ${e(dateLabel(run.finished_at))}, ${run.steps.filter(s=>s.ok).length} de ${run.steps.length} pasos correctos.`:''} Detalle en ${loreLink('#sistema','Estado del sistema')}.`;}
 for(const [pattern,text] of GLOSSARY){if(pattern.test(q)&&/que (es|significa|son)|significa|define|diferencia|explica/.test(q))return text;}
 if(/actor(es)? recurrente|quien(es)? aparece|stakeholder|mapa de actores|con quien (me )?relaciono|aliados|interlocutor/.test(q)){const s=p.stakeholders;if(!s)return 'No tengo el mapa de actores de esta cartera.';const soc=s.actors.filter(a=>a.type==='Sociedad').slice(0,5),st=s.actors.filter(a=>a.type==='Estado').slice(0,4);return `En los ${e(s.conflicts)} conflictos de ${e(p.company.name)} (2012-2025), los actores que más se repiten son:<br><b>Comunidades y organizaciones:</b> ${soc.map(a=>`${e(a.name)} (${a.conflicts})`).join('; ')||'—'}.<br><b>Estado:</b> ${st.map(a=>`${e(a.name)} (${a.conflicts})`).join('; ')}.<br>Detalle en ${loreLink('#conflictos','Mis conflictos')} → Mapa de actores. <small>Fuente: base de actores de la Defensoría 2012-2025.</small>`;}
 if(/mapa|satelit|sentinel|comunidades.*(conces|oleoducto)|pasivo|territorio dice/.test(q)&&!/que es|significa/.test(q)){const n=p.map_reading||[];return `Esto dice el mapa de ${e(p.company.name)}:<br>${n.map(x=>`• <b>${e(x.title)}:</b> ${e(x.text)}`).join('<br>')}<br>En ${loreLink('#territorio','Territorio')} puedes cambiar a <b>Satélite</b> para ver las imágenes reales Sentinel-2 y activar los focos de conflicto 2012-2025.`;}
 if(/reporte|informe mensual|pdf/.test(q))return `Ve a ${loreLink('#reportes','Reportes')} y descarga el reporte: lleva tu nombre, un resumen ejecutivo, una agenda sugerida, una ficha por conflicto y cinco figuras explicadas. Para PDF, ábrelo y usa Imprimir → Guardar como PDF.`;
 if(/alerta|urgente|prioridad|gestionar hoy|atencion/.test(q)){const a=p.alerts||[];if(!a.length)return 'No hay alertas activas con las fuentes incorporadas. Eso no significa que no haya riesgo.';return `Tienes <b>${a.length}</b> alertas (${p.alert_summary?.alta||0} altas, ${p.alert_summary?.media||0} medias, ${p.alert_summary?.baja||0} bajas). Las primeras:<br>${a.slice(0,3).map(x=>`• <b>${e(x.title)}</b>: ${e(x.detail.slice(0,140))}`).join('<br>')}<br>Todas en ${loreLink('#alertas','Alertas')}.`;}
 if(/prensa|noticia|medio|periodic/.test(q)){const m=p.media?.items||[];if(!m.length)return 'No hay notas de prensa en la ventana de 120 días.';return `En 120 días hay <b>${p.media.total}</b> notas sobre tu operación. Las más recientes:<br>${m.slice(0,4).map(i=>`• ${loreLink(i.url,i.title)} <small>(${e(i.outlet)}, ${e(dateLabel(i.published))})</small>`).join('<br>')}`;}
 const myCase=loreFind(q,p.cases||[],c=>[c.name,c.district,c.province].join(' '))[0];const myHistory=loreFind(q,p.linked_history||[],h=>h.name,h=>[h.district,h.description].join(' '))[0];
 const remoteCase=loreSubstantiveCase(q,myCase);if(!STATIC&&p.coverage?.ai_available&&remoteCase)return await loreRemoteAnswer(question,[],remoteCase.id);
 if(myCase&&!/pais|peru|nacional/.test(q)){const a=myCase.actors||{};const ev=(myCase.events||[]).filter(x=>x.kind!=='reporte oficial').slice(0,3);if(/quien|gestionar|actor|parte/.test(q))return `En <b>${e(myCase.name)}</b> las partes son: ${e((a.primarios||'no informadas').slice(0,500))}.<br>Intervienen: ${e((a.secundarios||'no informado').slice(0,250))}.<br>Median o supervisan: ${e((a.terciarios||'no informado').slice(0,200))}.<br><small>Fuente: ficha oficial de la Defensoría.</small>${loreCaseSources(myCase,loreContext())}${loreActionMarkup([{type:'open_case',case_id:String(myCase.id)}],loreContext())}`;return `<b>${e(myCase.name)}</b> · ${e(myCase.status)} · ${e(myCase.phase||'sin fase')} · ${myCase.dialogue?'con diálogo':'sin diálogo reportado'}.<br>${e((myCase.original_description||myCase.summary||'').slice(0,320))}<br>${(myCase.commitments||[]).length?`Compromisos reportados: ${myCase.commitments.length}. `:''}${ev.length?`Lo último que dicen otras fuentes:<br>${ev.map(x=>`• ${e(x.lane)}: ${e(x.title.slice(0,90))}`).join('<br>')}`:''}<br>${loreCaseSources(myCase,loreContext())}${loreActionMarkup([{type:'open_case',case_id:String(myCase.id)}],loreContext())}`;}
 if(myHistory&&!myCase){const a=(p.alerts||[]).find(x=>x.rule==='sin_cierre'&&normalize(x.title).includes(normalize(myHistory.name).slice(0,20)));return `<b>${e(myHistory.name)}</b> es parte del historial de ${e(p.company.name)}: ${e(myHistory.district||'distrito no informado')}, registrado de ${e(myHistory.first_period)} a ${e(myHistory.last_period)}; último estado: ${e(myHistory.last_status||'sin estado')}.<br>${myHistory.description?e(myHistory.description.slice(0,260))+'<br>':''}Partes: ${e(((myHistory.actors||{}).primarios||'no informadas').slice(0,220))}.${a?'<br>⚠️ Tiene una alerta: no hay un cierre reportado. Conviene confirmar con relaciones comunitarias.':''}<br><small>Fuente: base de reportes de la Defensoría 2012-2025.</small>`;}
 if(/historic|historia|desde|antes|20(1|2)\d|anos|quince/.test(q)){if(!state.national)await loadNational();const h=state.national?.history;if(!h)return 'No tengo el historial cargado.';const deps=Object.keys(h.departments||{});const dep=deps.find(d=>q.includes(normalize(d)));const year=(q.match(/20(1[2-9]|2[0-5])/)||[])[0];let cases=h.cases||[];if(dep)cases=cases.filter(c=>normalize(c.department)===normalize(dep));if(year)cases=cases.filter(c=>c.first_period<=year+'-12'&&c.last_period>=year+'-01');if(/antamina|bambas|petroper/.test(q))cases=cases.filter(c=>normalize([c.companies,c.name].join(' ')).includes(q.match(/antamina|bambas|petroper/)[0]));return `En la base 2012-2025 hay <b>${cases.length}</b> conflictos${dep?' en '+e(dep):''}${year?' con registro en '+year:''}. ${cases.length?'Algunos: '+cases.slice(0,5).map(c=>e(c.name.slice(0,60))+` (${e(c.first_period)}–${e(c.last_period)}, ${e(c.last_status||'s/d')})`).join('; ')+'.':''}<br><small>Fuente: base de tesis construida con los reportes mensuales de la Defensoría.</small>`;}
 if(/cuant|pais|peru|region|departamento|nacional|tipo|socioambiental|donde hay/.test(q)){if(!state.national)await loadNational();const all=state.national?.cases||[];const region=[...new Set(all.map(c=>c.region))].find(r=>q.includes(normalize(r)));const type=Object.keys(TYPE_COLORS).find(t=>q.includes(normalize(t).split(' ')[0])&&normalize(t).split(' ')[0].length>5);let list=all;if(region)list=list.filter(c=>c.region===region);if(type)list=list.filter(c=>c.type===type);return `El reporte vigente de la Defensoría (${e(periodLabel(state.national?.period))}) tiene <b>${list.length}</b> conflictos activos con ficha${region?' en '+e(region):' en el país'}${type?' de tipo '+e(type.toLowerCase()):''}. ${list.length&&list.length<=8?list.map(c=>'• '+e(c.name)).join('<br>'):''}<br>Explóralos en ${loreLink('#pais','Conflictos del país')}.`;}
 if(!state.national)await loadNational();
 const found=[...loreFind(q,state.national?.cases||[],c=>[c.name,c.location].join(' '),c=>[c.description,c.actors?.primarios].join(' ')).slice(0,3).map(c=>`• <b>${e(c.name)}</b> (${e(c.region)}, ${e(c.phase)}): ${e(c.description.slice(0,140))}…`),...loreFind(q,state.national?.history?.cases||[],c=>[c.name,c.district].join(' '),c=>[c.department,c.companies].join(' ')).slice(0,2).map(c=>`• Historial: <b>${e(c.name.slice(0,80))}</b> (${e(c.department||'')}, ${e(c.first_period)}–${e(c.last_period)})`)];
 if(!STATIC&&p.coverage?.ai_available)return await loreRemoteAnswer(question,found);
 return found.length?`Esto encontré en los datos:<br>${found.join('<br>')}<br><small>Fuentes: reporte vigente de la Defensoría y base histórica 2012-2025.</small>`:`No encontré eso en los datos de la plataforma, y prefiero no inventar. Prueba preguntarme por tus alertas, un conflicto por su nombre, una región, un año o un término como "fase de acuerdos".`;}
function loreMessage(html,who){const box=$('#lore-messages');if(!box)return;box.insertAdjacentHTML('beforeend',`<div class="lore-msg ${who}">${who==='lore'?`<span class="lore-avatar">${LORE_SVG}</span>`:''}<div>${html}</div></div>`);box.scrollTop=box.scrollHeight;}
let loreBusy=false;
async function loreAsk(text){if(!text.trim()||loreBusy)return;loreBusy=true;const input=$('#lore-input'),send=$('#lore-form button[type="submit"]');if(input)input.disabled=true;if(send)send.disabled=true;document.querySelectorAll('[data-lore-q]').forEach(b=>b.disabled=true);loreMessage(e(text),'user');loreMessage('<span class="lore-typing">Lore está pensando…</span>','lore');const pending=$('#lore-messages')?.lastElementChild;try{let answer;try{answer=await loreAnswer(text);}catch{answer='No pude completar la consulta. Las pantallas y fuentes siguen disponibles; intenta de nuevo.';}pending?.remove();loreMessage(answer,'lore');}finally{loreBusy=false;if(input){input.disabled=false;input.focus();}if(send)send.disabled=false;document.querySelectorAll('[data-lore-q]').forEach(b=>b.disabled=false);}}
function initLore(){if($('#lore-button'))return;initLoreReadActions();document.body.insertAdjacentHTML('beforeend',`<button id="lore-button" class="lore-button" type="button" aria-label="Abrir a Lore, la asistente">${LORE_SVG}<span>Pregúntale a Lore</span></button><section id="lore-panel" class="lore-panel" hidden aria-label="Lore, asistente de PulsoTerritorial"><header><span class="lore-avatar big">${LORE_SVG}</span><div><strong>Lore</strong><small>Tu llamita asistente · responde con los datos de la plataforma</small></div><button class="icon-button" id="lore-close" aria-label="Cerrar">${icon('close')}</button></header><div id="lore-messages" class="lore-messages" aria-live="polite"></div><div class="lore-chips">${['¿Por dónde empiezo?','¿Qué alertas tengo?','¿Quiénes son los actores recurrentes?','¿Qué dice el mapa?','Explícame esta pantalla','¿Cuántos conflictos hay en Áncash?','¿Qué es la fase de acuerdos?','¿De dónde salen los datos?'].map(t=>`<button type="button" data-lore-q="${e(t)}">${e(t)}</button>`).join('')}</div><form id="lore-form"><input id="lore-input" placeholder="Escribe tu pregunta…" maxlength="300" autocomplete="off"><button class="button button-primary" type="submit">Enviar</button></form></section>`);$('#lore-button').addEventListener('click',()=>toggleLore(true));$('#lore-close').addEventListener('click',()=>toggleLore(false));$('#lore-form').addEventListener('submit',ev=>{ev.preventDefault();const i=$('#lore-input');loreAsk(i.value);i.value='';});document.addEventListener('click',ev=>{const c=ev.target.closest?.('[data-lore-q]');if(c)loreAsk(c.dataset.loreQ);});}
function toggleLore(open){const panel=$('#lore-panel');panel.hidden=!open;$('#lore-button').classList.toggle('hidden',open);if(open&&!$('#lore-messages').children.length)loreMessage(`¡Hola${state.session?', '+e(state.session.user.split(' ')[0]):''}! Soy <b>Lore</b> 🦙. Te ayudo a entender tus conflictos y a usar la plataforma. Elige una pregunta o escríbeme.`,'lore');if(open)$('#lore-input').focus();}
function boot(){hydrateIcons();$('#login-form').addEventListener('submit',login);$('#logout-button').addEventListener('click',logout);const session=readSession();if(!session){$('#login-screen').hidden=false;$('#login-user').focus();}else startSession(session);$('#account-button').addEventListener('click',()=>$('#account-dialog').showModal());$('#help-button').addEventListener('click',()=>$('#info-dialog').showModal());$('#menu-button').addEventListener('click',()=>$('.sidebar').classList.toggle('open'));$('#refresh-button').addEventListener('click',refresh);window.addEventListener('hashchange',navigate);document.addEventListener('click',event=>{const target=event.target.closest('button,[data-case]');if(!target)return;if(target.dataset.case){openCase(target.dataset.case);return;}if(target.hasAttribute('data-close-case')){state.selectedCase=null;render();return;}if(target.dataset.mapView){state.threeD=target.dataset.mapView==='3d';document.querySelectorAll('[data-map-view]').forEach(b=>b.classList.toggle('active',b.dataset.mapView===target.dataset.mapView));for(const {map} of state.maps){map.easeTo({pitch:state.threeD?52:0,bearing:state.threeD?-12:0,duration:700});if(map.getSource('pulso-terrain'))map.setTerrain(state.threeD?{source:'pulso-terrain',exaggeration:1.25}:null);}return;}if(target.id==='chart-range'){state.chartAll=!state.chartAll;render();}if(target.id==='retry-button')loadPortfolio();if(target.id==='print-report'){const report=window.open(reportURL(),'_blank','noopener');toast('Usa la opción Imprimir del navegador para guardar el reporte como PDF.');}if(target.id==='interpret-button')interpret();});document.addEventListener('change',event=>{const el=event.target;if(el.id==='period-select'){state.period=el.value;loadPortfolio();}if(el.id==='case-status'){state.status=el.value;render();}if(el.dataset.layer){for(const entry of state.maps){if(el.dataset.layer==='cases'){entry.markers.forEach(marker=>marker.getElement().style.display=el.checked?'':'none');}else(entry.layers[el.dataset.layer]||[]).forEach(id=>entry.map.setLayoutProperty(id,'visibility',el.checked?'visible':'none'));}}});document.addEventListener('input',event=>{if(event.target.id==='case-search'){const value=event.target.value,position=event.target.selectionStart;state.query=value;render();const input=$('#case-search');input.focus();input.setSelectionRange(position,position);}});document.addEventListener('keydown',event=>{if(['Enter',' '].includes(event.key)&&event.target.matches('tr[data-case]')){event.preventDefault();openCase(event.target.dataset.case);}});}
if(typeof document!=='undefined')document.addEventListener('DOMContentLoaded',boot);


// PULSO_LORE_READ_ACTIONS_V1
function loreContext(){return {payload:state.payload,national:state.national,selectedCase:state.selectedCase,view:state.view,baseURL:location.href};}
function runLoreAction(raw){const action=validateLoreAction(raw,loreContext());if(!action)return false;if(action.type==='open_case'){openCase(action.case_id);return true;}if(action.type==='navigate'){if(location.hash==='#'+action.view)navigate();else location.hash='#'+action.view;return true;}return false;}
function loreApiUnavailable(reason,found){return `<small class="lore-response-mode">IA no disponible: ${e(String(reason).slice(0,350))}</small><br>${found.length?'La búsqueda local sí encontró:<br>'+found.join('<br>'):'Puedes seguir consultando las fichas, fuentes y alertas locales. Este fallo no demuestra ausencia de evidencia.'}`;}
function initLoreReadActions(){if(document.querySelector('link[data-lore-tools]'))return;const style=document.createElement('link');style.rel='stylesheet';style.href=new URL('./lore_tools.css',import.meta.url).href;style.dataset.loreTools='1';document.head.append(style);document.addEventListener('click',event=>{const button=event.target.closest?.('[data-lore-action]');if(!button)return;let action;try{action=JSON.parse(button.dataset.loreAction);}catch{return;}if(runLoreAction(action)){loreMessage('Abrí la selección solicitada en la plataforma.','lore');}else{loreMessage('Esa acción no está disponible en esta cartera.','lore');}});}

// PULSO_LORE_CASE_PRIORITY_V1
function loreSubstantiveCase(q,namedCase){
 const cases=state.payload?.cases||[];
 const chosen=namedCase||cases.find(c=>String(c.id)===String(state.selectedCase));
 if(!chosen)return null;
 if(/\b(?:pais|peru|nacional)\b/.test(q)||/cuant|cantidad|numero/.test(q))return null;
 if(/\b(?:quien|quienes|actores?|partes|interlocutor)\b/.test(q)&&!/\b(?:analiza|compara|evalua)\b/.test(q))return null;
 if(!/\b(?:resume|resumen|sintetiza|analiza|explica|compara|evalua|prioriza|describe|demandas?|reclamos?|compromisos?|acuerdos?|evolucion|cambios?|riesgos?|que|como|cual|cuales)\b|\?/.test(q))return null;
 return chosen;
}
async function loreRemoteAnswer(question,found=[],caseId=null){
 try{
  const r=await fetch('/api/ask',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({company:state.company,period:state.period,case_id:caseId||state.selectedCase||null,view:state.view,question})});
  const res=await r.json();
  if(r.ok&&(res.answer||res.records?.length))return renderLoreApiReply(res,loreContext());
  return loreApiUnavailable(res.error||'El proveedor no pudo responder.',found);
 }catch{return loreApiUnavailable('No pude conectar con la IA. La consulta local sigue disponible.',found);}
}
